<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { deepClone } from '../core/clone.ts';
import { useWorkspaceStore } from '../core/store.ts';
import type { TavernRegex } from '../types.ts';

const props = defineProps<{ index: number | null }>();

const store = useWorkspaceStore();
const 测试文本 = ref('这里放一段测试文本，例如 <thinking>思考过程</thinking> 正文内容。');

const 原文 = computed<TavernRegex | null>(() =>
  props.index === null ? null : (store.slot.regexes[props.index] ?? null),
);

const 草稿 = ref<TavernRegex | null>(null);
watch(
  原文,
  value => {
    草稿.value = value ? deepClone(value) : null;
  },
  { immediate: true },
);

/**
 * 实时测试用本地 JS 正则预览。
 * 不走酒馆的 formatAsTavernRegexedString 的原因: 那个 API 需要真实楼层上下文
 * （深度、角色卡名），在编辑器里做即时预览反而会给出误导性结果。
 */
const 测试 = computed(() => {
  if (!草稿.value) return { ok: false, text: '', error: '' };
  const 原始 = 草稿.value.find_regex.trim();
  if (!原始) return { ok: false, text: '', error: '查找表达式为空' };

  const 匹配 = 原始.match(/^\/([\s\S]*)\/([a-z]*)$/i);
  const 模式 = 匹配 ? 匹配[1] : 原始;
  const 标志 = 匹配 ? 匹配[2] : 'g';

  try {
    const re = new RegExp(模式, 标志.includes('g') ? 标志 : `${标志}g`);
    return { ok: true, text: 测试文本.value.replace(re, 草稿.value.replace_string), error: '' };
  } catch (error) {
    return { ok: false, text: '', error: error instanceof Error ? error.message : String(error) };
  }
});

function 保存() {
  if (!草稿.value || props.index === null) return;
  const 列表 = [...store.slot.regexes];
  列表[props.index] = 草稿.value;
  store.slot.regexes = 列表;
  store.save();
  toastr.success('已保存', '预设缝合助手');
}
</script>

<template>
  <div v-if="!草稿" class="flex-1 min-h-0 overflow-y-auto p-4 text-xs text-muted leading-relaxed">
    在中栏点选一条目标正则开始编辑。
  </div>

  <div v-else class="flex-1 min-h-0 overflow-y-auto p-2.5 space-y-2.5 text-xs">
    <label class="block">
      <span class="text-muted">脚本名</span>
      <input v-model="草稿.script_name" class="w-full mt-0.5" />
    </label>

    <label class="block">
      <span class="text-muted">查找（形如 /pattern/flags）</span>
      <input v-model="草稿.find_regex" class="w-full mt-0.5 font-mono text-[11px]" />
    </label>

    <label class="block">
      <span class="text-muted">替换为</span>
      <textarea v-model="草稿.replace_string" rows="3" class="w-full mt-0.5 text-[11px]" />
    </label>

    <label class="flex items-center gap-1.5 cursor-pointer">
      <input v-model="草稿.enabled" type="checkbox" />启用
    </label>

    <details class="border border-line rounded-md">
      <summary class="px-2 py-1 cursor-pointer select-none text-muted">高级</summary>
      <div class="p-2 space-y-2 border-t border-line">
        <div>
          <div class="text-muted mb-1">作用范围</div>
          <div class="flex flex-wrap gap-x-3 gap-y-1">
            <label class="flex items-center gap-1 cursor-pointer">
              <input v-model="草稿.source.user_input" type="checkbox" />用户输入
            </label>
            <label class="flex items-center gap-1 cursor-pointer">
              <input v-model="草稿.source.ai_output" type="checkbox" />AI 输出
            </label>
            <label class="flex items-center gap-1 cursor-pointer">
              <input v-model="草稿.source.slash_command" type="checkbox" />斜杠命令
            </label>
            <label class="flex items-center gap-1 cursor-pointer">
              <input v-model="草稿.source.world_info" type="checkbox" />世界书
            </label>
            <label class="flex items-center gap-1 cursor-pointer" title="酒馆的读写过程不保留该选项，写入后会丢失">
              <input v-model="草稿.source.reasoning" type="checkbox" />推理 <span class="text-warn">⚠</span>
            </label>
          </div>
        </div>

        <div>
          <div class="text-muted mb-1">用途</div>
          <div class="flex flex-wrap gap-x-3 gap-y-1">
            <label class="flex items-center gap-1 cursor-pointer">
              <input v-model="草稿.destination.display" type="checkbox" />仅格式显示
            </label>
            <label class="flex items-center gap-1 cursor-pointer">
              <input v-model="草稿.destination.prompt" type="checkbox" />仅格式提示词
            </label>
          </div>
        </div>

        <label class="flex items-center gap-1.5 cursor-pointer">
          <input v-model="草稿.run_on_edit" type="checkbox" />编辑时运行
        </label>

        <div class="flex gap-3">
          <label class="flex-1">
            最小深度
            <input
              :value="草稿.min_depth ?? ''"
              type="number"
              class="w-full mt-0.5"
              @input="草稿.min_depth = ($event.target as HTMLInputElement).value === '' ? null : Number(($event.target as HTMLInputElement).value)"
            />
          </label>
          <label class="flex-1">
            最大深度
            <input
              :value="草稿.max_depth ?? ''"
              type="number"
              class="w-full mt-0.5"
              @input="草稿.max_depth = ($event.target as HTMLInputElement).value === '' ? null : Number(($event.target as HTMLInputElement).value)"
            />
          </label>
        </div>

        <div>
          <div class="text-muted mb-1">修剪字符串（每行一个）</div>
          <textarea
            :value="草稿.trim_strings.join('\n')"
            rows="3"
            class="w-full text-[11px]"
            @input="草稿.trim_strings = ($event.target as HTMLTextAreaElement).value.split('\n').filter(Boolean)"
          />
        </div>
      </div>
    </details>

    <div>
      <div class="text-muted mb-1">实时测试</div>
      <textarea v-model="测试文本" rows="2" class="w-full text-[11px]" />
      <pre
        v-if="测试.ok"
        class="mt-1 p-2 rounded-md bg-surface2/70 text-[11px] whitespace-pre-wrap max-h-32 overflow-y-auto font-mono"
      >{{ 测试.text }}</pre>
      <div v-else class="mt-1 text-danger">正则无效：{{ 测试.error }}</div>
    </div>

    <button class="px-3 py-1 rounded-md bg-accent text-accent-text font-medium" @click="保存">保存</button>
  </div>
</template>
