<script setup lang="ts">
/**
 * 预设缝合助手 · 手机版外壳。
 *
 * 与桌面版的唯一区别是布局：
 * 桌面版是三栏并排，手机版把所有界面切换收进顶部的页签栏，内容单列堆叠。
 * 核心逻辑（core/）与各功能面板（components/）与桌面版完全共用，
 * 所以两边功能一致、修一处两边都好。
 *
 * 布局基准（iOS 竖屏 844×390pt）：
 *   安全区  env(safe-area-inset-top / bottom) 自适应
 *   导航栏  44pt   —— 模式切换 + 槽位下拉 + 主题 + 关闭
 *   页签栏  50pt   —— 预设 / 条目 / 变量 / AI / 比对 / 编辑
 *   操作条  50pt   —— 骨架 + 同步并启用
 *   页边距  16pt   其余间距一律取 4 的倍数
 *
 * 外加一颗可拖动的悬浮球（components/FloatingBall.vue）：
 * 手机竖屏握持时大拇指够不到顶部页签栏，球把「切页签」挪到手指能碰到的地方。
 * 初始停左下角（避开操作条），位置存手机版专属的设置键，不回写共用工作区数据。
 *
 * 页签名用短名「比对 / 编辑」而不是「条目比对 / 条目编辑」：
 * 358pt 可用宽度下，6 个页签按 13px 排全名需要 359px，差 1px 装不下。
 */
import { computed, inject, onMounted, ref, watch, type Ref } from 'vue';
import FloatingBall from './components/FloatingBall.vue';
import AiAssistant from '../预设缝合助手/components/AiAssistant.vue';
import DiffView from '../预设缝合助手/components/DiffView.vue';
import GlobalParams from '../预设缝合助手/components/GlobalParams.vue';
import PresetPanel from '../预设缝合助手/components/PresetPanel.vue';
import PromptEditor from '../预设缝合助手/components/PromptEditor.vue';
import RegexEditor from '../预设缝合助手/components/RegexEditor.vue';
import RegenDialog from '../预设缝合助手/components/RegenDialog.vue';
import SourcePromptList from '../预设缝合助手/components/SourcePromptList.vue';
import SourceRegexList from '../预设缝合助手/components/SourceRegexList.vue';
import SplitHandle from '../预设缝合助手/components/SplitHandle.vue';
import TargetPromptList from '../预设缝合助手/components/TargetPromptList.vue';
import TargetRegexList from '../预设缝合助手/components/TargetRegexList.vue';
import VariableTable from '../预设缝合助手/components/VariableTable.vue';
import { 同步槽位, 导入槽位为源预设 } from '../预设缝合助手/core/actions.ts';
import { 用比对队列 } from '../预设缝合助手/core/compareQueue.ts';
import { useWorkspaceStore } from '../预设缝合助手/core/store.ts';
import type { PresetPrompt, TavernRegex, 编辑对象 } from '../预设缝合助手/types.ts';

const 关闭面板 = inject<() => void>('关闭面板', () => {
  console.warn('[预设缝合助手] 未注入关闭能力');
});
const 面板文档 = inject<Document | null>('面板文档', null);

const store = useWorkspaceStore();

/**
 * AI 生成但还没确认的条数。
 *
 * 挂在「AI」页签的徽标上：AI 助手自带的结果列表要滚到面板底部才看得见，
 * 有了徽标，人在「条目」页签也能一眼看到有没有待办。
 * （「条目」页签的 TargetPromptList 隐藏了结果区，不这么补一下就会丢信息。）
 */
const 待确认数 = computed(() => store.slot.aiResults.filter(r => !r.applied).length);

/* ============ 模式：预设缝合 / 正则缝合 ============ */

/**
 * 模式切换放在左上角，切模式会【整套换掉页签栏】。
 * 正则模式用不上「条目 / 变量 / 比对 / 编辑」，
 * 预设模式也用不上「正则 / 正则编辑」—— 把它们一直挂在页签栏里，
 * 用户点进去只会看到空页，不如按模式给两套。
 */
const 模式 = ref<'prompt' | 'regex'>('prompt');
const 模式菜单 = ref(false);
const 模式菜单位置 = ref({ x: 0, y: 0 });
const 模式名 = computed(() => (模式.value === 'prompt' ? '预设缝合' : '正则缝合'));

/**
 * 模式菜单用 fixed 定位而不是 absolute：
 * 导航栏带 backdrop-filter，会在自身建立堆叠上下文，
 * absolute 子元素容易被压在内容区下面或被裁掉。
 */
function 开模式菜单(event: MouseEvent) {
  const 矩形 = (event.currentTarget as HTMLElement).getBoundingClientRect();
  模式菜单位置.value = { x: 矩形.left, y: 矩形.bottom + 4 };
  模式菜单.value = !模式菜单.value;
}

function 切模式(新: 'prompt' | 'regex') {
  模式.value = 新;
  模式菜单.value = false;
  页签.value = '预设';
  编辑对象.value = null;
  待采用.value = null;
  关闭对比();
}

/* ============ 页签 ============ */

const 页签 = ref('预设');

/** 数量徽标：超过两位数就收成 99+，否则页签会被撑开 */
function 计数(n: number): string {
  return n > 99 ? '99+' : String(n);
}

const 页签表 = computed(() => {
  if (模式.value === 'regex') {
    return [
      { key: '预设', 名: '预设', 数: store.workspace.imports.length },
      { key: '正则', 名: '正则', 数: store.slot.regexes.length },
      { key: 'AI', 名: 'AI', 数: 待确认数.value },
      { key: '正则编辑', 名: '正则编辑', 数: 0 },
    ];
  }
  return [
    { key: '预设', 名: '预设', 数: store.workspace.imports.length },
    { key: '条目', 名: '条目', 数: store.slot.prompts.length },
    { key: '变量', 名: '变量', 数: 0 },
    { key: 'AI', 名: 'AI', 数: 待确认数.value },
    { key: '比对', 名: '比对', 数: 对比队列.value.length },
    { key: '编辑', 名: '编辑', 数: 0 },
  ];
});

/* ============ 上下分栏比例 ============ */

/**
 * 生成上下分栏的 flex 样式。
 *
 * 必须用 computed 返回【对象】，不能在模板里写模板字符串：
 * 组件里若拿到未解包的 ref，`${ref} 1 0%` 会生成 "[object Object] 1 0%"，
 * 非法 CSS 被整条丢弃，上半区撑满、分隔线掉到最底部。
 */
function 分栏样式(比例: Ref<number>, 上半: boolean) {
  return computed(() => ({ flex: `${上半 ? 比例.value : 100 - 比例.value} 1 0%` }));
}

const 预设比例 = ref(60);
const 预设上 = 分栏样式(预设比例, true);
const 预设下 = 分栏样式(预设比例, false);

const 条目比例 = ref(50);
const 条目上 = 分栏样式(条目比例, true);
const 条目下 = 分栏样式(条目比例, false);

const 正则比例 = ref(50);
const 正则上 = 分栏样式(正则比例, true);
const 正则下 = 分栏样式(正则比例, false);

/* ============ 槽位 ============ */

const 槽位菜单 = ref(false);

function 选槽位(id: string) {
  store.切换槽位(id);
  槽位菜单.value = false;
}

function 新建槽位() {
  store.新建槽位();
  槽位菜单.value = false;
}

function 槽位操作(动作: '重命名' | '同步' | '导入' | '删除') {
  const id = store.slot.id;
  槽位菜单.value = false;
  if (动作 === '重命名') {
    const 名 = prompt('槽位名称（也是同步到酒馆时的预设名）', store.slot.name);
    if (名 !== null) store.重命名槽位(id, 名.trim());
  } else if (动作 === '同步') {
    同步槽位(store, id);
  } else if (动作 === '导入') {
    const 新id = 导入槽位为源预设(store, id);
    if (新id) 选中预设(新id);
  } else {
    store.删除槽位(id);
  }
}

/* ============ 主题 ============ */

function 应用主题() {
  if (!面板文档) return;
  面板文档.documentElement.dataset.theme = store.workspace.theme;
}
watch(() => store.workspace.theme, 应用主题);
onMounted(应用主题);

/* ============ 交互 ============ */

const activePresetId = ref<string | null>(null);
const 正则索引 = ref<number | null>(null);
const 源批量模式 = ref(false);
const 同步中 = ref(false);

/**
 * 条目编辑器当前编辑的对象：目标条目 / AI 生成结果 / 源预设条目，三处共用。
 * 与桌面版同一套抽象，见 types.ts 的 编辑对象。
 */
const 编辑对象 = ref<编辑对象 | null>(null);

/** 从变量树点冲突值行时带来的「采用这个值」，在编辑器顶部做成浮条 */
const 待采用 = ref<{ 变量名: string; 值: string } | null>(null);

/** 条目比对的队列逻辑，与桌面版共用（core/compareQueue.ts） */
const {
  队列: 对比队列,
  当前: 当前对比,
  开始: 队列开始,
  写入: 写入当前,
  放弃: 放弃当前,
  关闭: 关闭对比,
  重做展开,
  重做中,
  打开重做,
  执行重做,
} = 用比对队列();

/** 目标条目列表里该高亮哪一条 */
const 选中目标uid = computed(() => (编辑对象.value?.类型 === 'target' ? 编辑对象.value.uid : null));

/** 在「预设」页签里点了一份待缝合预设 → 自然下一步就是去挑条目 */
function 选中预设(id: string) {
  activePresetId.value = id;
  页签.value = '条目';
}

/** 建队列并切到「比对」页签 */
function 开始对比(ids: string[]) {
  if (ids.length === 0) return;
  队列开始(ids);
  页签.value = '比对';
  编辑对象.value = null;
  待采用.value = null;
}

/** 点开某条条目开始编辑 */
function 打开编辑(对象: 编辑对象 | null, 动作: { 变量名: string; 值: string } | null = null) {
  编辑对象.value = 对象;
  待采用.value = 对象 ? 动作 : null;
  页签.value = '编辑';
}

/** AI 助手面板里点「查看目标」 */
function 打开目标(uid: string) {
  打开编辑({ 类型: 'target', uid });
}

/** 点了编辑器顶部那条「采用这个值」 */
function 采用当前值() {
  const 待 = 待采用.value;
  if (!待) return;
  store.裁决变量(待.变量名, 待.值);
  toastr.success(`已采用「${待.变量名}」的这个值`, '预设缝合助手');
  待采用.value = null;
}

function 加入目标(prompt: PresetPrompt, presetId: string) {
  store.切换目标条目(prompt, presetId);
  // 加入后顺手打开它，省掉「刚加进去的那条在哪」的找
  打开编辑({ 类型: 'target', uid: `${presetId}::${prompt.id}` });
}

function 加入正则(regex: TavernRegex) {
  store.切换目标正则(regex);
}

/** 核弹级操作，必须二次确认 */
function 清空全部() {
  槽位菜单.value = false;
  const 确认 = confirm('确定要清空全部数据吗？将删除：所有已导入的源预设、所有缝合槽位及其目标条目与正则、AI 助手的输入与自定义提示词。此操作无法撤销。');
  if (!确认) return;
  store.清空全部();
  编辑对象.value = null;
  待采用.value = null;
  关闭对比();
  正则索引.value = null;
  activePresetId.value = null;
  toastr.success('已清空全部数据', '预设缝合助手');
}

async function 执行同步() {
  同步中.value = true;
  try {
    await 同步槽位(store, store.slot.id);
  } finally {
    同步中.value = false;
  }
}
</script>

<template>
  <!--
    高度用 h-full 而不是 h-screen：
    panel.css 里 html、body 都是 height:100%，而 iframe 的尺寸由宿主按 visualViewport
    实时钉住，所以 100% 才是「真正看得见的那块」。
    100vh 取的是大视口（地址栏收起时的最大高度），比可见区高一截 —— 那正是顶栏
    能被状态栏 / 悬浮地址栏压住的源头之一，别再用它。
    w-full 同理：100vw 含滚动条宽度，会凭空多出横向溢出。

    安全区优先取宿主递进来的变量（--面板安全区*）。
    iframe 内部没有 viewport meta，自己量 env(safe-area-inset-*) 恒为 0，
    只有宿主（酒馆的 index.html 声明了 viewport-fit=cover）量得到真值。
    变量缺失时回退 env()，所以桌面浏览器上表现不变。
  -->
  <div
    class="h-full w-full flex flex-col text-body overflow-hidden"
    style="
      padding-top: var(--面板安全区上, env(safe-area-inset-top));
      padding-right: var(--面板安全区右, env(safe-area-inset-right));
      padding-bottom: var(--面板安全区下, env(safe-area-inset-bottom));
      padding-left: var(--面板安全区左, env(safe-area-inset-left));
      box-sizing: border-box;
    "
  >
    <!-- ============ 导航栏 44pt ============ -->
    <header class="glass-strong shrink-0 px-4 flex items-center gap-2" style="height: 44px">
      <!-- 模式切换（左上角） -->
      <button
        class="shrink-0 h-9 px-2 rounded-md flex items-center gap-1 text-[13px] font-semibold border transition-colors"
        :class="模式菜单 ? 'border-accent text-accent' : 'border-transparent'"
        title="切换缝合模式（预设缝合 / 正则缝合）"
        @click.stop="开模式菜单($event)"
      >
        <i class="fa-solid fa-blender text-accent text-2xl" />
        <span class="whitespace-nowrap">{{ 模式 === 'prompt' ? '预设' : '正则' }}</span>
        <i class="fa-solid fa-caret-down text-[10px] opacity-70" />
      </button>

      <!-- 槽位：手机上用下拉，省横向空间 -->
      <button
        class="flex-1 min-w-0 h-9 text-left px-2 rounded-md border border-line text-[13px] flex items-center gap-1"
        @click.stop="槽位菜单 = !槽位菜单"
      >
        <span class="truncate flex-1">{{ store.slot.name || '未命名槽位' }}</span>
        <span class="text-muted shrink-0 text-[11px]">{{ store.slot.prompts.length }}条</span>
        <i class="fa-solid fa-caret-down text-[10px] opacity-60 shrink-0" />
      </button>

      <button
        class="shrink-0 w-11 h-11 -mr-2 rounded-md flex items-center justify-center"
        :title="store.workspace.theme === 'dark' ? '切到日间' : '切到夜间'"
        @click.stop="store.切换主题()"
      >
        <i
          class="fa-solid text-2xl"
          :class="store.workspace.theme === 'dark' ? 'fa-sun' : 'fa-moon'"
        />
      </button>

      <button
        class="shrink-0 w-11 h-11 -mr-2 rounded-md flex items-center justify-center"
        title="关闭面板"
        @click="关闭面板()"
      >
        <i class="fa-solid fa-xmark text-2xl" />
      </button>
    </header>

    <!-- ============ 页签栏 50pt ============ -->
    <nav
      class="glass shrink-0 px-4 border-b border-line flex items-center gap-0.5"
      style="height: 50px"
    >
      <button
        v-for="项 in 页签表"
        :key="项.key"
        class="flex-1 min-w-0 h-10.5 rounded-lg text-[13px] transition-colors flex items-center justify-center gap-0.5"
        :class="
          页签 === 项.key
            ? 'bg-accent text-accent-text font-medium'
            : 'text-muted hover:bg-surface2'
        "
        @click="页签 = 项.key"
      >
        <span class="truncate">{{ 项.名 }}</span>
        <span v-if="项.数" class="opacity-75 text-[11px] shrink-0">{{ 计数(项.数) }}</span>
      </button>
    </nav>

    <!-- ============ 内容区 ============ -->
    <!--
      列表类页签（预设 / 条目 / 变量 / 正则）用 v-if：
      组件重建代价小，也避免所有重型组件同时挂载。

      AI / 比对 / 编辑 / 正则编辑 用 v-show：
      它们各自持有【长时任务与半成品】—— AI 正在生成、比对队列排到第几条、
      编辑器里还没保存的改动。切走再切回来不能把这些清掉，
      桌面版右栏正是为这个才用的 v-show。
    -->
    <main class="flex-1 min-h-0 flex flex-col px-4 py-2 overflow-hidden">
      <!-- ---------- 预设 ---------- -->
      <template v-if="页签 === '预设'">
        <div class="min-h-0 flex flex-col" :style="预设上">
          <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
            <PresetPanel v-model:批量模式="源批量模式" @选中预设="选中预设" />
          </div>
        </div>
        <SplitHandle @拖动="比例 => (预设比例 = 比例)" />
        <div class="min-h-0 flex flex-col" :style="预设下">
          <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
            <GlobalParams />
          </div>
        </div>
      </template>

      <!-- ---------- 条目：源（上）/ 目标（下） ---------- -->
      <template v-else-if="页签 === '条目'">
        <div class="min-h-0 flex flex-col" :style="条目上">
          <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
            <SourcePromptList
              v-model:批量模式="源批量模式"
              :preset-id="activePresetId"
              @选择="加入目标"
              @查看="(p, id) => 打开编辑({ 类型: 'source', presetId: id, promptId: p.id })"
            />
          </div>
        </div>
        <SplitHandle @拖动="比例 => (条目比例 = 比例)" />
        <div class="min-h-0 flex flex-col" :style="条目下">
          <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
            <!--
              隐藏结果区：AI 生成结果已经独立到「AI」页签，
              这里只留目标条目。不藏的话就是「源 / 目标 / 结果」三层套娃，
              两条分隔线在手机上根本拖不动。
            -->
            <TargetPromptList
              :选中uid="选中目标uid"
              隐藏结果区
              @选中="打开编辑({ 类型: 'target', uid: $event })"
              @开始对比="开始对比"
            />
          </div>
        </div>
      </template>

      <!-- ---------- 变量 ---------- -->
      <template v-else-if="页签 === '变量'">
        <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
          <VariableTable :预设id="activePresetId" @编辑条目="打开编辑" />
        </div>
      </template>

      <!-- ---------- 正则：源（上）/ 目标（下） ---------- -->
      <template v-else-if="页签 === '正则'">
        <div class="min-h-0 flex flex-col" :style="正则上">
          <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
            <SourceRegexList @选中="加入正则" />
          </div>
        </div>
        <SplitHandle @拖动="比例 => (正则比例 = 比例)" />
        <div class="min-h-0 flex flex-col" :style="正则下">
          <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
            <TargetRegexList
              @选中编辑器="
                i => {
                  正则索引 = i;
                  页签 = '正则编辑';
                }
              "
            />
          </div>
        </div>
      </template>

      <!-- ---------- AI ---------- -->
      <!--
        AI 助手独占这一屏，不再另配「生成结果」下半区 ——
        因为 AiAssistant 自带的结果列表（滚动区底部）功能更全：
        带勾选、全选、批量替换，把它藏起来换成精简版反而减功能。
        待确认条数已经挂到页签徽标上补偿可发现性。
      -->
      <div v-show="页签 === 'AI'" class="flex-1 min-h-0 flex flex-col">
        <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
          <AiAssistant
            :track="模式 === 'regex' ? 'regex' : 'entry'"
            @开始对比="开始对比"
            @查看目标="打开目标"
          />
        </div>
      </div>

      <!-- ---------- 条目比对 ---------- -->
      <div v-show="页签 === '比对'" class="flex-1 min-h-0 flex flex-col">
        <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
          <!--
            ⚠️ 中文 prop 名【绝对不能】写成 `:对比-结果`。
            Vue 的 kebab→camel 用 /-(\w)/g，而 \w 只匹配 ASCII —— `-结` 匹配不上，
            连字符不会被去掉，prop 名成了字面量 "对比-结果"，与声明的「对比结果」对不上，
            组件会【静默拿到 undefined】：不报错、不警告、构建全绿，只是界面永远空。
          -->
          <DiffView
            :对比结果="当前对比"
            :对比剩余="对比队列.length"
            @写入="写入当前"
            @重新生成="打开重做"
            @放弃="放弃当前"
            @关闭对比="关闭对比"
          />
        </div>
      </div>

      <!-- ---------- 条目编辑 ---------- -->
      <div v-show="页签 === '编辑'" class="flex-1 min-h-0 flex flex-col">
        <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
          <PromptEditor :对象="编辑对象" :待采用="待采用" @采用值="采用当前值" />
        </div>
      </div>

      <!-- ---------- 正则编辑 ---------- -->
      <div v-show="页签 === '正则编辑'" class="flex-1 min-h-0 flex flex-col">
        <div class="glass rounded-xl overflow-hidden flex-1 min-h-0 flex flex-col">
          <RegexEditor :index="正则索引" />
        </div>
      </div>
    </main>

    <!-- ============ 操作条 50pt ============ -->
    <footer
      class="glass-strong shrink-0 px-4 flex items-center gap-2 border-t border-line"
      style="height: 50px"
    >
      <span class="text-[11px] text-muted truncate flex-1">
        骨架
        <span :class="store.skeleton ? 'text-accent' : 'text-danger'">
          {{ store.skeleton?.name ?? '未选' }}
        </span>
      </span>
      <button
        class="shrink-0 h-9 px-4 rounded-lg bg-accent text-accent-text font-medium text-[13px] disabled:opacity-40"
        :disabled="同步中"
        @click="执行同步"
      >
        {{ 同步中 ? '同步中…' : '同步并启用' }}
      </button>
    </footer>

    <!-- ============ 浮层 ============ -->

    <!-- 模式选择菜单 -->
    <template v-if="模式菜单">
      <div class="fixed inset-0 z-40" @click="模式菜单 = false" />
      <div
        class="fixed z-50 glass-strong rounded-lg p-1 min-w-52 text-xs"
        :style="{ left: 模式菜单位置.x + 'px', top: 模式菜单位置.y + 'px' }"
      >
        <button
          v-for="项 in [
            { key: 'prompt' as const, 名: '预设缝合', 说明: '条目 + 变量，输出为酒馆预设' },
            { key: 'regex' as const, 名: '正则缝合', 说明: '随预设绑定同步输出的正则' },
          ]"
          :key="项.key"
          class="w-full text-left px-2 py-2 rounded-md transition-colors"
          :class="模式 === 项.key ? 'bg-accent-soft/40 text-accent' : 'hover:bg-surface2'"
          @click="切模式(项.key)"
        >
          <div class="font-medium">{{ 项.名 }}</div>
          <div class="text-[10px] text-muted">{{ 项.说明 }}</div>
        </button>
      </div>
    </template>

    <!-- 槽位菜单 -->
    <template v-if="槽位菜单">
      <div class="fixed inset-0 z-40" @click="槽位菜单 = false" />
      <div
        class="fixed left-4 right-4 z-50 glass-strong rounded-xl p-2 space-y-1 text-xs max-h-[70vh] overflow-y-auto"
        :style="{ top: 'calc(env(safe-area-inset-top, 0px) + 52px)' }"
      >
        <div class="text-[10px] text-muted px-1 pb-1 border-b border-line">缝合槽位</div>
        <button
          v-for="项 in store.workspace.slots"
          :key="项.id"
          class="w-full text-left px-2 py-2 rounded-md flex items-center gap-2"
          :class="项.id === store.slot.id ? 'bg-accent-soft/50 text-accent' : 'hover:bg-surface2'"
          @click="选槽位(项.id)"
        >
          <i class="fa-solid fa-layer-group" />
          <span class="truncate flex-1">{{ 项.name || '未命名' }}</span>
          <span class="text-muted">{{ 项.prompts.length }} / {{ 项.regexes.length }}</span>
        </button>

        <div class="border-t border-line my-1" />
        <div class="text-[10px] text-muted px-1 pb-1">对当前槽位操作</div>
        <div class="grid grid-cols-2 gap-1">
          <button class="px-2 py-2 rounded-md border border-line hover:border-accent" @click="槽位操作('重命名')">
            <i class="fa-solid fa-pen mr-1" />重命名
          </button>
          <button class="px-2 py-2 rounded-md border border-line hover:border-accent" @click="槽位操作('同步')">
            <i class="fa-solid fa-upload mr-1" />同步到酒馆
          </button>
          <button class="px-2 py-2 rounded-md border border-line hover:border-accent" @click="槽位操作('导入')">
            <i class="fa-solid fa-circle-down mr-1" />导入为素材
          </button>
          <button
            class="px-2 py-2 rounded-md border border-line hover:border-danger hover:text-danger disabled:opacity-40"
            :disabled="store.workspace.slots.length <= 1"
            @click="槽位操作('删除')"
          >
            <i class="fa-solid fa-trash-can mr-1" />删除槽位
          </button>
        </div>

        <div class="border-t border-line my-1" />
        <div class="grid grid-cols-2 gap-1">
          <button class="px-2 py-2 rounded-md border border-dashed border-line-strong hover:border-accent" @click="新建槽位">
            <i class="fa-solid fa-plus mr-1" />新建槽位
          </button>
          <button
            class="px-2 py-2 rounded-md border border-line hover:border-danger hover:text-danger"
            @click="清空全部"
          >
            <i class="fa-solid fa-trash-can mr-1" />清空全部
          </button>
        </div>
      </div>
    </template>

    <!--
      悬浮球：把「切页签」挪到大拇指够得到的地方。
      传的是同一个 页签表 —— 所以它的目录和上面那条页签栏永远逐项一致，
      切模式（预设/正则）时两边一起变，不需要额外同步。
      ⚠️ 中文 prop 名不能带连字符：写成 `:页签-表` 会静默绑定失败拿到 undefined。
    -->
    <FloatingBall :页签表="页签表" :当前="页签" @切换="键 => (页签 = 键)" />

    <!-- 重新生成：输入修改意见发给 AI（与桌面版同一个弹窗组件） -->
    <RegenDialog
      :展开="重做展开"
      :条目名="当前对比?.name ?? ''"
      :忙碌="重做中"
      @发送="执行重做"
      @关闭="重做展开 = false"
    />
  </div>
</template>
