<script setup lang="ts">
import { ref, watch } from 'vue';

const props = defineProps<{
  展开: boolean;
  /** 要重做的是哪一条，显示在标题上 */
  条目名: string;
  /** 正在调 AI */
  忙碌: boolean;
}>();

const emit = defineEmits<{
  发送: [意见: string];
  关闭: [];
}>();

const 意见 = ref('');

// 每次打开都清空，避免上一条的意见串到下一条
watch(
  () => props.展开,
  open => {
    if (open) 意见.value = '';
  },
);

function 发送() {
  const 文本 = 意见.value.trim();
  if (!文本) {
    toastr.warning('先写点修改意见，AI 才知道要往哪个方向改', '预设缝合助手');
    return;
  }
  emit('发送', 文本);
}
</script>

<template>
  <div v-if="展开" class="fixed inset-0 z-50 flex items-center justify-center p-4" @click.self="emit('关闭')">
    <div class="absolute inset-0 bg-black/50" />

    <div class="relative glass-strong rounded-xl w-full max-w-lg flex flex-col overflow-hidden">
      <div class="px-3 py-2 shrink-0 border-b border-line flex items-center gap-2 text-xs">
        <i class="fa-solid fa-rotate-right text-accent" />
        <span class="font-medium">重新生成</span>
        <span class="text-muted truncate max-w-64">{{ 条目名 }}</span>
        <button class="ml-auto text-muted hover:text-danger" @click="emit('关闭')">
          <i class="fa-solid fa-xmark" />
        </button>
      </div>

      <div class="p-3 space-y-2">
        <p class="text-[11px] text-muted leading-relaxed">
          AI 会以当前这版为底、按你的意见重做一遍，结果仍然回到比对界面，不会直接写进目标。
        </p>
        <textarea
          v-model="意见"
          rows="5"
          class="w-full text-xs"
          placeholder="例如：语气再克制一点，去掉比喻；保留原本的分点结构"
          @keydown.ctrl.enter="发送"
        />
      </div>

      <div class="px-3 py-2 shrink-0 border-t border-line flex items-center gap-2">
        <span class="text-[10px] text-muted flex-1">Ctrl+Enter 直接发送</span>
        <button
          class="px-3 py-1 rounded-md bg-accent text-accent-text font-medium text-xs disabled:opacity-50"
          :disabled="忙碌"
          @click="发送"
        >
          <i class="fa-solid fa-paper-plane mr-1" />{{ 忙碌 ? '生成中…' : '发送给 AI' }}
        </button>
        <button
          class="px-3 py-1 rounded-md border border-line hover:border-line-strong text-xs disabled:opacity-40"
          :disabled="忙碌"
          @click="emit('关闭')"
        >
          取消
        </button>
      </div>
    </div>
  </div>
</template>
