<script setup lang="ts">
import { computed, ref } from 'vue';
import InjectDialog from './InjectDialog.vue';
import {
  已中止错误,
  合并组,
  默认提示词,
  精判,
  聚类,
  粗筛,
  正则筛选,
  对齐改写,
  取术语参照,
  取注入内容,
  type 候选条目,
} from '../core/ai.ts';
import { deepClone } from '../core/clone.ts';
import { useWorkspaceStore } from '../core/store.ts';
import { 中止生成 } from '../core/tavern.ts';
import { VARIABLE_CONSOLE_UID, type PresetPrompt, type TargetPrompt } from '../types.ts';

const props = defineProps<{ track: 'entry' | 'variable' | 'regex' }>();

const emit = defineEmits<{
  /** 进「条目比对」页看新旧对照。点一条 = 只有那一条的队列 */
  开始对比: [ids: string[]];
  /** 点注入列表里的目标条目 → 用条目编辑器打开它 */
  查看目标: [uid: string];
}>();

/* ============ 注入条目 ============ */

const 注入弹窗 = ref(false);
const 注入页签 = ref<'已注入' | '目标条目' | '源预设'>('目标条目');

/**
 * 目前注入的条目 = 目标栏里没被排除的全部。
 *
 * 【缺省即全注入】—— 空排除名单意味着「一条都没排除」，也就是全都注入。
 * 所以这里必须列出全部目标条目，而不是列出某个「已注入名单」。
 */
const 已注入条目 = computed(() => {
  const 排 = store.workspace.ai.injectionExcluded;
  return 槽位.value.prompts.filter(t => !排.includes(t._uid));
});

function 打开注入(页签: '已注入' | '目标条目' | '源预设') {
  注入页签.value = 页签;
  注入弹窗.value = true;
}

/**
 * 注入条目：把它们的 uid 从排除名单里拿掉。
 *
 * 来自源预设的条目会**先逐条加进目标预设**再算作参照 ——
 * 因为它们原本不在目标栏里，不先加进来的话这个 uid 在目标里根本不存在，
 * AI 改写时拿不到内容，注入等于空转。
 */
function 执行注入(条目: { 预设id: string; promptId: string }[]) {
  const 待加 = 条目.filter(对 => !槽位.value.prompts.some(t => t._uid === `${对.预设id}::${对.promptId}`));

  let 新加 = 0;
  if (待加.length > 0) {
    const 表 = 待加
      .map(对 => {
        const 预设 = store.workspace.imports.find(i => i.id === 对.预设id);
        const prompt = 预设 ? store.条目(预设).find(p => p.id === 对.promptId) : undefined;
        return 预设 && prompt ? { prompt, presetId: 对.预设id } : null;
      })
      .filter(Boolean) as { prompt: PresetPrompt; presetId: string }[];
    新加 = store.批量加入条目(表);
  }

  const 该注入 = new Set(条目.map(对 => `${对.预设id}::${对.promptId}`));
  store.workspace.ai.injectionExcluded = store.workspace.ai.injectionExcluded.filter(u => !该注入.has(u));
  store.save();

  toastr.success(
    新加 ? `已逐条加入目标 ${新加} 条，并全部设为 AI 参照` : `已设为 AI 参照 ${条目.length} 条`,
    '预设缝合助手',
  );
}

/**
 * 取消注入：只把 uid 记进排除名单。
 *
 * 【不碰目标栏】—— 用户要的是「不给 AI 看」，不是「把条目从新预设里删掉」。
 * 这两件事混在一起会很吓人：想调个参照，结果条目没了。
 */
function 执行取消注入(键列表: string[]) {
  const 已有 = new Set(store.workspace.ai.injectionExcluded);
  for (const k of 键列表) 已有.add(k);
  store.workspace.ai.injectionExcluded = [...已有];
  store.save();
  toastr.success(`已取消注入 ${键列表.length} 条（目标条目不受影响）`, '预设缝合助手');
}

function 清空注入() {
  const 数 = 已注入条目.value.length;
  if (数 === 0) return;
  if (!confirm(`确定取消全部 ${数} 条注入吗？目标条目本身不会被删除。`)) return;
  store.workspace.ai.injectionExcluded = 槽位.value.prompts.map(t => t._uid);
  store.save();
  toastr.success('已清空注入条目', '预设缝合助手');
}

const store = useWorkspaceStore();
const 运行中 = ref(false);
const 阶段 = ref('');
const 展开预设 = ref(false);
const 展开注入 = ref(false);
const 展开提示词 = ref(false);
/** AI 生成条目的勾选，用于「替换选中」 */
const 结果勾选 = ref<Set<string>>(new Set());

/** 用户点停止后置为 true，各批量流程每轮都会检查 */
const 已中止 = ref(false);
/** 上一次执行的操作，用于「重新生成」 */
const 上次操作 = ref<null | (() => Promise<void>)>(null);

const 候选 = ref<{ uid: string; 名称: string; 分数: number; 理由: string }[]>([]);
const 候选勾选 = ref<Set<string>>(new Set());
const 正则候选 = ref<{ id: string; 名称: string; 理由: string }[]>([]);

const 槽位 = computed(() => store.slot);

/** 高级设置里「条目查找」用的关键词；正则筛选共用 */
const 查找关键词 = computed({
  get: () => store.workspace.ai.searchKeyword,
  set: (v: string) => {
    store.workspace.ai.searchKeyword = v;
    store.save();
  },
});

/** 底部对话框里「改写」用的关键词 */
const 改写关键词 = computed({
  get: () => store.workspace.ai.rewriteKeyword,
  set: (v: string) => {
    store.workspace.ai.rewriteKeyword = v;
    store.save();
  },
});

/**
 * 底部对话框当前选中的改写方式。
 * 做成「先选方式、再点发送」而不是一个按钮直接开跑：
 * 对话框里填的要求是两边共用的，先选定方式能避免误点跑错。
 */
const 改写模式 = ref<'对齐' | '合并' | null>(null);

/** 对话框里填的要求。空串表示只做通用处理，由 AI 按默认规则来 */
function 需求参数(): string {
  return 改写关键词.value.trim();
}

/** 点方式按钮：选中；再点一次取消 */
function 切换改写模式(模式: '对齐' | '合并') {
  改写模式.value = 改写模式.value === 模式 ? null : 模式;
}

const 提示词 = computed(() => store.workspace.ai.prompts);

function 改提示词(键: 'filter' | 'rewrite' | 'regex', 值: string) {
  store.workspace.ai.prompts = { ...store.workspace.ai.prompts, [键]: 值 };
  store.save();
}

function 恢复默认(键: 'filter' | 'rewrite' | 'regex') {
  改提示词(键, '');
}

/* ============ 运行控制 ============ */

/**
 * 统一包一层：负责运行态、中止标志、错误分类、「重新生成」的记录。
 * 主动停止不算失败 —— 报错会让用户以为出了问题。
 */
async function 运行(操作: () => Promise<void>, 重试: () => Promise<void>) {
  if (运行中.value) return;
  运行中.value = true;
  已中止.value = false;
  上次操作.value = 重试;
  try {
    await 操作();
  } catch (error) {
    if (error instanceof 已中止错误) {
      toastr.info('已停止', '预设缝合助手');
    } else {
      console.error(error);
      toastr.error(`执行失败：${error instanceof Error ? error.message : String(error)}`, '预设缝合助手');
    }
  } finally {
    运行中.value = false;
    阶段.value = '';
  }
}

/** 一键清空 AI 助手：候选结果在组件里，AI 生成条目与配置在 store 里，三处都要清 */
function 清空AI() {
  候选.value = [];
  候选勾选.value = new Set();
  正则候选.value = [];
  结果勾选.value = new Set();
  上次操作.value = null;
  阶段.value = '';
  store.清空AI结果();
  store.清空AI配置();
  toastr.success('已清空 AI 助手', '预设缝合助手');
}

function 停止() {
  已中止.value = true;
  // 尽力而为：酒馆原生 generateRaw 用的是它自己的 AbortController，
  // stopGeneration() 中止的是另一个对象，所以正在飞行中的请求打断不了。
  // 真正的停止靠「已中止」标志在下一轮循环时生效。
  中止生成();
}

function 重新生成() {
  if (运行中.value || !上次操作.value) return;
  上次操作.value();
}

/* ============ 对话框上的三个键 ============ */

/**
 * 发送：用对话框上方选中的方式跑一次改写。
 * 不在这里直接开跑「对齐」是因为对话框里的要求对两种方式都适用，
 * 让用户先明确选定方式，比猜意图安全。
 */
function 发送() {
  if (运行中.value) return;
  if (!改写模式.value) {
    toastr.warning('先在上面选「对齐润色」或「合并同主题」', '预设缝合助手');
    return;
  }
  执行改写(改写模式.value);
}

/** 暂停：中止批量处理 */
function 暂停() {
  停止();
}

/** 重说：用同样的参数再跑一次 */
function 重说() {
  重新生成();
}

const 应中止 = () => 已中止.value;

/* ============ 搜索范围 ============ */

/** 本次参与搜索的源预设。没勾选时是全部 */
const 参与预设 = computed(() => {
  const 选中 = store.workspace.ai.selectedPresetIds;
  if (选中.length === 0) return store.workspace.imports;
  return store.workspace.imports.filter(i => 选中.includes(i.id));
});

const 是否限定预设 = computed(() => store.workspace.ai.selectedPresetIds.length > 0);

function 切换预设(id: string) {
  const 当前 = store.workspace.ai.selectedPresetIds;
  store.workspace.ai.selectedPresetIds = 当前.includes(id) ? 当前.filter(x => x !== id) : [...当前, id];
  store.save();
}

function 全选预设() {
  const 全部 = store.workspace.imports.map(i => i.id);
  store.workspace.ai.selectedPresetIds =
    store.workspace.ai.selectedPresetIds.length === 全部.length ? [] : 全部;
  store.save();
}

function 全部条目(): 候选条目[] {
  const 结果: 候选条目[] = [];
  for (const imported of 参与预设.value) {
    for (const p of store.条目(imported)) {
      结果.push({
        uid: `${imported.id}::${p.id}`,
        name: `${imported.name} · ${p.name}`,
        excerpt: (p.content ?? '').replace(/\s+/g, ' ').slice(0, 120),
        content: p.content ?? '',
      });
    }
  }
  return 结果;
}

// 与比对界面里的「重新生成」共用同一份参照，抽在 core/ai.ts 里算
const 注入内容 = computed(() => 取注入内容(槽位.value.prompts, store.workspace.ai.injectionExcluded));

/* ============ 抓取条目 ============ */

async function 执行抓取() {
  if (!查找关键词.value.trim()) {
    toastr.warning('请先填写想要的效果关键词', '预设缝合助手');
    return;
  }
  const 全部 = 全部条目();
  if (全部.length === 0) {
    toastr.warning(是否限定预设.value ? '限定的预设里没有条目' : '还没有导入任何预设', '预设缝合助手');
    return;
  }

  await 运行(
    async () => {
      阶段.value = `粗筛中（共 ${全部.length} 条）…`;
      const 粗筛结果 = await 粗筛(全部, 查找关键词.value, 提示词.value.filter, 应中止);

      // 只对粗筛达标的条目做精判 —— 这是两级筛选省成本的关键
      const 入围 = 全部.filter(c => (粗筛结果.get(c.uid) ?? 0) >= 5).slice(0, 120);
      if (入围.length === 0) {
        toastr.info('没有找到相关条目，可以换个说法再试', '预设缝合助手');
        候选.value = [];
        return;
      }

      阶段.value = `精判中（${入围.length} 条）…`;
      const 精判结果 = await 精判(入围, 查找关键词.value, 提示词.value.filter, 应中止);
      const 名称表 = new Map(入围.map(c => [c.uid, c.name]));

      候选.value = 精判结果
        .filter(r => r.score >= 5)
        .map(r => ({ uid: r.uid, 名称: 名称表.get(r.uid) ?? r.uid, 分数: r.score, 理由: r.reason }))
        .sort((a, b) => b.分数 - a.分数);
      候选勾选.value = new Set(候选.value.map(c => c.uid));
      toastr.success(`找到 ${候选.value.length} 条相关条目`, '预设缝合助手');
    },
    执行抓取,
  );
}

function 收候选为条目(uid列表: string[]): { prompt: PresetPrompt; presetId: string }[] {
  const 结果: { prompt: PresetPrompt; presetId: string }[] = [];
  for (const uid of uid列表) {
    const [presetId, promptId] = uid.split('::');
    const imported = store.workspace.imports.find(i => i.id === presetId);
    if (!imported) continue;
    const prompt = store.条目(imported).find(p => p.id === promptId);
    if (prompt) 结果.push({ prompt, presetId });
  }
  return 结果;
}

function 加入勾选的候选() {
  const 数 = store.批量加入条目(收候选为条目([...候选勾选.value]));
  toastr.success(数 ? `已加入 ${数} 条` : '勾选的条目都已在目标中', '预设缝合助手');
}

function 加入候选(uid: string) {
  const 数 = store.批量加入条目(收候选为条目([uid]));
  if (!数) toastr.info('该条目已在目标中', '预设缝合助手');
}

function 切换候选勾选(uid: string) {
  const 下一个 = new Set(候选勾选.value);
  下一个.has(uid) ? 下一个.delete(uid) : 下一个.add(uid);
  候选勾选.value = 下一个;
}

/* ============ 改写（先预览，后写入） ============ */

// 同上：与比对界面共用，避免两处各算一套算出不一样的东西
const 术语参照 = computed(() => 取术语参照(store.skeleton));

/** 生成一个 AI 结果的 id */
function 新结果id(): string {
  return crypto?.randomUUID?.() ?? `ai-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/**
 * 执行改写。
 *
 * 结果【只进本地暂存】（`slot.aiResults`），不动目标条目 ——
 * 用户要在条目编辑器里逐条对比、或者点「全部替换」一次性覆盖，
 * 替换是一次显式决策，不再是改写的副作用。
 */
async function 执行改写(模式: '对齐' | '合并') {
  const 待改 = 槽位.value.prompts.filter(t => t._uid !== VARIABLE_CONSOLE_UID);
  if (待改.length === 0) {
    toastr.warning('目标栏里还没有条目', '预设缝合助手');
    return;
  }

  await 运行(
    async () => {
      let 已产出 = 0;

      if (模式 === '对齐') {
        for (let i = 0; i < 待改.length; i++) {
          阶段.value = `对齐润色 ${i + 1}/${待改.length}…`;
          const 条目 = 待改[i];
          if (应中止()) throw new 已中止错误();
          const 新内容 = await 对齐改写(
            条目.content ?? '',
            术语参照.value,
            注入内容.value,
            需求参数(),
            提示词.value.rewrite,
            应中止,
          );
          store.添加AI结果({
            id: 新结果id(),
            targetUids: [条目._uid],
            name: 条目.name,
            content: 新内容,
            mode: 'aligned',
            createdAt: Date.now(),
            applied: false,
          });
          已产出++;
        }
      } else {
        阶段.value = '聚类中…';
        const 分组 = await 聚类(
          待改.map(t => ({ uid: t._uid, name: t.name, content: t.content ?? '' })),
          需求参数(),
          提示词.value.rewrite,
          应中止,
        );
        const 待改表 = new Map(待改.map(t => [t._uid, t]));

        for (const [下标, 组] of 分组.entries()) {
          if (组.length <= 1) continue;
          阶段.value = `合并第 ${下标 + 1}/${分组.length} 组…`;
          const 成员 = 组.map(uid => 待改表.get(uid)).filter(Boolean) as TargetPrompt[];
          if (成员.length <= 1) continue;

          const 合并后 = await 合并组(
            成员.map(m => ({ name: m.name, content: m.content ?? '' })),
            需求参数(),
            提示词.value.rewrite,
            应中止,
          );
          store.添加AI结果({
            id: 新结果id(),
            targetUids: 组,
            name: 成员[0].name,
            content: 合并后,
            mode: 'merged',
            createdAt: Date.now(),
            applied: false,
          });
          已产出++;
        }
      }

      toastr.success(
        已产出
          ? `已生成 ${已产出} 条改写结果，在下方「AI 生成条目」里勾选后替换`
          : '没有产生任何改写结果',
        '预设缝合助手',
      );
    },
    () => 执行改写(模式),
  );
}

/* ============ AI 结果的替换 ============ */

/**
 * 还没确认替换的结果。
 * 已确认的从列表里消失：它的内容已经进了目标条目，
 * 再挂在待办列表里只会让人以为还有事没做完。
 */
const 待确认结果 = computed(() => 槽位.value.aiResults.filter(r => !r.applied));

function 切换结果勾选(id: string) {
  const 下一个 = new Set(结果勾选.value);
  下一个.has(id) ? 下一个.delete(id) : 下一个.add(id);
  结果勾选.value = 下一个;
}

/** 替换选中：交给 App 建对比队列，进条目编辑器逐条确认 */
function 替换选中() {
  const ids = [...结果勾选.value].filter(id => 待确认结果.value.some(r => r.id === id));
  if (ids.length === 0) {
    toastr.warning('先勾选要替换的条目', '预设缝合助手');
    return;
  }
  emit('开始对比', ids);
}

/** 全部替换：跳过逐条确认，一次覆盖 */
function 全部替换() {
  const 数 = 待确认结果.value.length;
  if (数 === 0) {
    toastr.info('没有待替换的条目', '预设缝合助手');
    return;
  }
  if (!confirm(`确定把 ${数} 条 AI 生成结果全部替换进目标条目吗？合并模式的结果会同时移除其余成员条目。`)) {
    return;
  }
  const 成功 = store.全部应用AI结果();
  结果勾选.value = new Set();
  toastr.success(`已替换 ${成功} / ${数} 条`, '预设缝合助手');
}

/* ============ 正则筛选 ============ */

async function 执行正则筛选() {
  if (!查找关键词.value.trim()) {
    toastr.warning('请先填写需求', '预设缝合助手');
    return;
  }
  const 参与集 = new Set(参与预设.value.map(i => i.id));
  const 全部 = store.正则来源.filter(e => 参与集.has(e.presetId));
  if (全部.length === 0) {
    toastr.warning('限定范围内没有正则', '预设缝合助手');
    return;
  }

  await 运行(
    async () => {
      阶段.value = `筛选中（共 ${全部.length} 条）…`;
      const 结果 = await 正则筛选(
        全部.map(e => ({
          id: e.regex.id,
          name: `${e.presetName} · ${e.regex.script_name}`,
          find: e.regex.find_regex,
        })),
        查找关键词.value,
        提示词.value.regex,
        应中止,
      );
      const 名称表 = new Map(全部.map(e => [e.regex.id, e.regex.script_name]));
      正则候选.value = 结果.map(r => ({ id: r.id, 名称: 名称表.get(r.id) ?? r.id, 理由: r.理由 }));
      toastr.success(`筛出 ${正则候选.value.length} 条相关正则`, '预设缝合助手');
    },
    执行正则筛选,
  );
}

function 加入正则(id: string) {
  const entry = store.正则来源.find(e => e.regex.id === id);
  if (!entry) return;
  if (槽位.value.regexes.some(r => r.id === id)) {
    toastr.info('该正则已在目标中', '预设缝合助手');
    return;
  }
  store.批量加入正则([deepClone(entry.regex)]);
}
</script>
<template>
  <div class="flex-1 min-h-0 flex flex-col">
    <!-- ============ 顶部固定：高级设置 ============ -->
    <details class="shrink-0 border-b border-line">
      <summary class="px-2.5 py-1.5 cursor-pointer select-none text-xs flex items-center gap-2">
        <i class="fa-solid fa-sliders" />
        <span class="flex-1">高级设置</span>
        <button
          class="px-1.5 py-0.5 rounded border border-line hover:border-danger hover:text-danger text-[10px] transition-colors"
          title="清空 AI 助手：查找与改写关键词、候选结果、AI 生成条目、来源限定、注入条目、自定义提示词"
          @click.prevent.stop="清空AI"
        >
          <i class="fa-solid fa-trash-can" /> 清空
        </button>
      </summary>

      <!--
        max-h 用 vh 而不是 %：面板高度链上有一环是 flex-1，
        百分比 max-height 在 flex 容器里解析不可靠，会退化成不限制。
        这一条是为了「展开后若超过 AI 助手的长度就出滚动条」。
      -->
      <div class="border-t border-line max-h-[45vh] overflow-y-auto p-2 space-y-2">
        <!-- （a）条目查找 -->
        <div class="rounded-md border border-line p-2">
          <div class="text-[11px] text-muted mb-1">
            {{ props.track === 'regex' ? '想要的正则效果' : '条目查找关键词' }}
          </div>
          <textarea
            v-model="查找关键词"
            rows="2"
            class="w-full text-xs"
            :placeholder="
              props.track === 'regex'
                ? '例如：清理思维链、去掉 AI 免责声明'
                : '例如：加强角色扮演的代入感、让旁白更克制'
            "
          />
          <button
            class="w-full mt-1 px-3 py-1.5 rounded-md bg-accent text-accent-text font-medium text-xs disabled:opacity-50"
            :disabled="运行中"
            @click="props.track === 'regex' ? 执行正则筛选() : 执行抓取()"
          >
            <i class="fa-solid fa-magnifying-glass mr-1" />
            {{ props.track === 'regex' ? '筛选相关正则' : '抓取相关条目' }}
          </button>
        </div>

        <!-- （b）限定搜索范围 -->
        <div>
          <button
            class="w-full text-left px-2 py-1 rounded-md bg-surface2 hover:bg-line text-xs flex items-center gap-1"
            @click="展开预设 = !展开预设"
          >
            <span class="flex-1">缝合来源预设</span>
            <span :class="是否限定预设 ? 'text-accent' : 'text-muted'">
              {{ 是否限定预设 ? `已选 ${store.workspace.ai.selectedPresetIds.length}` : '全部' }}
            </span>
          </button>
          <div v-if="展开预设" class="mt-1 border border-line rounded-md max-h-40 overflow-y-auto">
            <div class="flex items-center gap-2 px-2 py-1 border-b border-line text-[10px] text-muted">
              <span class="flex-1">不勾 = 在所有导入的预设里找</span>
              <button class="hover:text-accent" @click="全选预设">
                {{
                  store.workspace.ai.selectedPresetIds.length === store.workspace.imports.length
                    ? '全不选'
                    : '全选'
                }}
              </button>
            </div>
            <label
              v-for="item in store.workspace.imports"
              :key="item.id"
              class="flex items-center gap-1.5 px-2 py-0.5 text-xs hover:bg-surface2/60 cursor-pointer"
            >
              <input
                type="checkbox"
                :checked="store.workspace.ai.selectedPresetIds.includes(item.id)"
                @change="切换预设(item.id)"
              />
              <span class="truncate flex-1">{{ item.name }}</span>
              <span class="text-[10px] text-muted">{{ store.条目(item).length }}</span>
            </label>
            <div v-if="store.workspace.imports.length === 0" class="p-2 text-xs text-muted">
              还没有导入任何预设
            </div>
          </div>
        </div>

        <!-- （c）注入条目：只列现在注入了什么，增删走弹窗 -->
        <div>
          <div class="px-2 py-1 rounded-md bg-surface2 text-xs flex items-center gap-1">
            <span class="flex-1">注入条目（作为 AI 的固定参照）</span>
            <span :class="已注入条目.length ? 'text-accent font-medium' : 'text-muted'">
              已注入 {{ 已注入条目.length }} 条
            </span>
          </div>

          <!-- 只列出已经注入的条目。没注入的不铺在这里 ——
               展开就要能一眼确认「这次请求会带上什么」，而不是再扫一遍全表 -->
          <div class="mt-1 border border-line rounded-md max-h-44 overflow-y-auto">
            <div v-if="已注入条目.length === 0" class="p-2 text-[11px] text-muted">
              {{ 槽位.prompts.length === 0
                ? '目标栏还没有条目。'
                : '所有条目都被取消了注入。点下面的「注入」把要用的加回来。' }}
            </div>
            <div
              v-for="t in 已注入条目"
              :key="t._uid"
              class="flex items-center gap-1.5 px-2 py-0.5 text-xs hover:bg-surface2/60 cursor-pointer"
              :title="`查看「${t.name}」的内容`"
              @click="emit('查看目标', t._uid)"
            >
              <i class="fa-solid fa-check text-accent shrink-0 text-[10px]" />
              <span class="truncate flex-1 text-accent">{{ t.name }}</span>
            </div>
          </div>

          <div class="mt-1 flex gap-1.5">
            <button
              class="flex-1 px-2 py-1 rounded-md border border-accent text-accent text-xs hover:bg-accent-soft/30"
              title="挑条目注入为 AI 的固定参照"
              @click="打开注入('目标条目')"
            >
              <i class="fa-solid fa-plus mr-1" />注入
            </button>
            <button
              class="flex-1 px-2 py-1 rounded-md border border-line hover:border-line-strong text-xs disabled:opacity-40"
              :disabled="已注入条目.length === 0"
              title="取消某些条目的注入"
              @click="打开注入('已注入')"
            >
              <i class="fa-solid fa-minus mr-1" />移除
            </button>
            <button
              class="flex-1 px-2 py-1 rounded-md border border-line hover:border-danger hover:text-danger text-xs disabled:opacity-40"
              :disabled="已注入条目.length === 0"
              title="取消全部注入"
              @click="清空注入"
            >
              <i class="fa-solid fa-eraser mr-1" />清空
            </button>
          </div>
        </div>

        <!-- （d）系统提示词 -->
        <div>
          <button
            class="w-full text-left px-2 py-1 rounded-md bg-surface2 hover:bg-line text-xs"
            @click="展开提示词 = !展开提示词"
          >
            系统提示词（留空用内置默认）
          </button>
          <div v-if="展开提示词" class="mt-1 space-y-2">
            <div
              v-for="项 in [
                { 键: 'filter' as const, 名: '抓取 / 筛选' },
                { 键: 'rewrite' as const, 名: '改写 / 聚类 / 合并' },
                { 键: 'regex' as const, 名: '正则筛选' },
              ]"
              :key="项.键"
            >
              <div class="flex items-center gap-2">
                <span class="text-[11px] text-muted flex-1">{{ 项.名 }}</span>
                <button class="text-[10px] text-muted hover:text-accent" @click="恢复默认(项.键)">恢复默认</button>
              </div>
              <textarea
                :value="提示词[项.键]"
                rows="3"
                class="w-full mt-0.5 text-[11px]"
                :placeholder="默认提示词[项.键]"
                @input="改提示词(项.键, ($event.target as HTMLTextAreaElement).value)"
              />
            </div>
          </div>
        </div>
      </div>
    </details>

    <!-- ============ 中部：唯一可滚动区 ============ -->
    <div class="flex-1 min-h-0 overflow-y-auto p-2.5 space-y-2.5">
      <!-- 运行状态 / 控制 -->
      <div v-if="运行中" class="space-y-1 text-xs">
        <div class="flex items-center gap-2">
          <i class="fa-solid fa-spinner fa-spin" :class="已中止 ? 'text-warn' : 'text-accent'" />
          <span class="flex-1" :class="已中止 ? 'text-warn' : 'text-accent'">
            {{ 已中止 ? '正在停止…' : 阶段 || '处理中…' }}
          </span>
          <button
            v-if="!已中止"
            class="px-2 py-0.5 rounded border border-danger text-danger hover:bg-danger/10"
            title="停止批量处理"
            @click="停止"
          >
            <i class="fa-solid fa-stop" /> 停止
          </button>
        </div>
        <p v-if="已中止" class="text-[10px] text-muted leading-relaxed">
          已经发出、正在生成的那一条无法中途打断（酒馆原生 generateRaw 的限制），
          它结束后就会停下，已完成的部分会保留。
        </p>
      </div>
      <template v-if="props.track !== 'regex'">
        <!-- 候选条目 -->
        <div v-if="候选.length" class="space-y-1">
          <div class="flex items-center gap-2 text-[11px] text-muted">
            <span class="flex-1">候选 {{ 候选.length }} 条</span>
            <button
              class="hover:text-accent"
              @click="候选勾选 = 候选勾选.size ? new Set() : new Set(候选.map(c => c.uid))"
            >
              {{ 候选勾选.size ? '全不选' : '全选' }}
            </button>
          </div>
          <div v-for="item in 候选" :key="item.uid" class="border border-line rounded-md p-1.5 text-[11px] flex gap-1.5">
            <input
              type="checkbox"
              class="shrink-0 mt-0.5"
              :checked="候选勾选.has(item.uid)"
              @change="切换候选勾选(item.uid)"
            />
            <div class="flex-1 min-w-0">
              <div class="truncate">{{ item.名称 }}</div>
              <div class="text-muted"><span class="text-accent">{{ item.分数 }}分</span> · {{ item.理由 }}</div>
            </div>
            <button class="shrink-0 text-accent hover:underline self-start" @click="加入候选(item.uid)">加入</button>
          </div>
          <button
            class="w-full px-3 py-1 rounded-md border border-accent text-accent text-xs disabled:opacity-40"
            :disabled="候选勾选.size === 0"
            @click="加入勾选的候选"
          >
            加入勾选的 {{ 候选勾选.size }} 条
          </button>
        </div>

        <!-- AI 生成条目：本地暂存，确认后才替换 -->
        <div v-if="待确认结果.length" class="border-t border-line pt-2 space-y-1">
          <div class="flex items-center gap-2 text-[11px] text-muted">
            <span class="flex-1">AI 生成条目 · 待确认 {{ 待确认结果.length }} 条</span>
            <button
              class="hover:text-accent"
              @click="结果勾选 = 结果勾选.size ? new Set() : new Set(待确认结果.map(r => r.id))"
            >
              {{ 结果勾选.size ? '全不选' : '全选' }}
            </button>
          </div>
          <!--
            点一行 = 打开这一条的对比界面（原条目 vs AI 版本）。
            勾选框只负责「替换选中」的批量选择，两者互不干扰。
          -->
          <div
            v-for="r in 待确认结果"
            :key="r.id"
            class="border border-line rounded-md p-1.5 text-[11px] flex gap-1.5 cursor-pointer transition-colors hover:border-line-strong"
            title="点击进「条目比对」，与它要替换的原条目做前后对照"
            @click="emit('开始对比', [r.id])"
          >
            <input
              type="checkbox"
              class="shrink-0 mt-0.5"
              :checked="结果勾选.has(r.id)"
              @click.stop
              @change="切换结果勾选(r.id)"
            />
            <div class="flex-1 min-w-0">
              <div class="truncate">{{ r.name }}</div>
              <div class="text-muted truncate">
                <span class="text-accent">
                  {{ r.mode === 'merged' ? `由 ${r.targetUids.length} 条合并` : '对齐润色' }}
                </span>
                · {{ r.content.slice(0, 40) }}{{ r.content.length > 40 ? '…' : '' }}
              </div>
            </div>
            <button
              class="shrink-0 text-muted hover:text-danger self-start"
              title="丢弃这条结果，目标条目不受影响"
              @click.stop="store.移除AI结果(r.id)"
            >
              <i class="fa-solid fa-xmark" />
            </button>
          </div>
        </div>

      </template>

      <!-- 正则轨：候选正则 -->
      <template v-else>
        <div v-if="正则候选.length" class="space-y-1">
          <div class="text-[11px] text-muted">候选 {{ 正则候选.length }} 条</div>
          <div
            v-for="item in 正则候选"
            :key="item.id"
            class="border border-line rounded-md p-1.5 text-[11px] flex gap-1.5"
          >
            <div class="flex-1 min-w-0">
              <div class="truncate">{{ item.名称 }}</div>
              <div class="text-muted">{{ item.理由 }}</div>
            </div>
            <button class="shrink-0 text-accent hover:underline self-start" @click="加入正则(item.id)">加入</button>
          </div>
        </div>
        <p class="text-[10px] text-muted leading-relaxed">
          正则之间的冲突（重复、高度相似、作用域重叠）会在中栏右侧标黄提示。
        </p>
      </template>
    </div>

    <!-- ============ 底部固定：功能按钮 + 对话框 ============ -->
    <div v-if="props.track !== 'regex'" class="shrink-0 border-t border-line p-2.5 space-y-1.5">
      <!-- 功能按钮组：在对话框上方 -->
      <div class="text-[10px] text-muted">
        改写当前槽位的目标条目（先生成预览）· 先选方式，再在下面说要求
      </div>
      <div class="flex gap-1.5">
        <button
          class="flex-1 px-2 py-1 rounded-md border text-xs transition-colors disabled:opacity-50"
          :class="
            改写模式 === '对齐'
              ? 'border-accent bg-accent-soft/40 text-accent font-medium'
              : 'border-line hover:border-accent'
          "
          :disabled="运行中"
          title="选中后用下面的「发送」执行；再点一次取消选择"
          @click="切换改写模式('对齐')"
        >
          <i class="fa-solid fa-wand-magic-sparkles mr-1" />对齐润色
        </button>
        <button
          class="flex-1 px-2 py-1 rounded-md border text-xs transition-colors disabled:opacity-50"
          :class="
            改写模式 === '合并'
              ? 'border-accent bg-accent-soft/40 text-accent font-medium'
              : 'border-line hover:border-accent'
          "
          :disabled="运行中"
          title="选中后用下面的「发送」执行；再点一次取消选择"
          @click="切换改写模式('合并')"
        >
          <i class="fa-solid fa-layer-group mr-1" />合并同主题
        </button>
      </div>
      <div class="flex gap-1.5">
        <button
          class="flex-1 px-2 py-1 rounded-md border border-accent text-accent text-xs disabled:opacity-40"
          :disabled="结果勾选.size === 0 || 运行中"
          title="进条目编辑器逐条对比，确认后才写入"
          @click="替换选中"
        >
          <i class="fa-solid fa-code-compare mr-1" />替换选中（{{ 结果勾选.size }}）
        </button>
        <button
          class="flex-1 px-2 py-1 rounded-md border border-line hover:border-accent text-xs disabled:opacity-40"
          :disabled="待确认结果.length === 0 || 运行中"
          title="跳过逐条确认，一次覆盖全部待确认结果"
          @click="全部替换"
        >
          <i class="fa-solid fa-forward mr-1" />全部替换
        </button>
      </div>

      <!-- 对话框：钉在最底部，发送 / 暂停 / 重说 贴着它 -->
      <div class="rounded-md border border-line overflow-hidden">
        <textarea
          v-model="改写关键词"
          rows="3"
          class="w-full text-xs border-0 focus:outline-none resize-none"
          placeholder="说说你想怎么改。例如：统一成克制冷静的旁白语气，去掉夸张比喻"
          @keydown.ctrl.enter="发送"
        />
        <div class="flex items-center gap-1.5 px-1.5 py-1 border-t border-line bg-surface2/50">
          <span class="text-[10px] text-muted flex-1 truncate">
            {{
              运行中
                ? 已中止
                  ? '正在暂停…'
                  : 阶段 || '处理中…'
                : 改写模式
                  ? `当前方式：${改写模式 === '对齐' ? '对齐润色' : '合并同主题'}`
                  : '先选上面的改写方式'
            }}
          </span>
          <button
            class="px-2 py-0.5 rounded bg-accent text-accent-text text-[11px] font-medium disabled:opacity-40"
            :disabled="运行中"
            title="用选中的方式执行改写（Ctrl+Enter）"
            @click="发送"
          >
            <i class="fa-solid fa-paper-plane mr-1" />发送
          </button>
          <button
            class="px-2 py-0.5 rounded border border-danger text-danger text-[11px] disabled:opacity-40"
            :disabled="!运行中 || 已中止"
            title="中止批量处理"
            @click="暂停"
          >
            <i class="fa-solid fa-pause mr-1" />暂停
          </button>
          <button
            class="px-2 py-0.5 rounded border border-line hover:border-accent text-[11px] disabled:opacity-40"
            :disabled="运行中 || !上次操作"
            title="用同样的参数再跑一次"
            @click="重说"
          >
            <i class="fa-solid fa-rotate-right mr-1" />重说
          </button>
        </div>
      </div>
    </div>

    <!-- 注入条目弹窗：屏幕中央，顶部三个切换 -->
    <InjectDialog
      :展开="注入弹窗"
      :初始页签="注入页签"
      @注入="执行注入"
      @取消注入="执行取消注入"
      @关闭="注入弹窗 = false"
    />
  </div>
</template>
