        for (const [下标, 组] of 分组.entries()) {
          if (组.length <= 1) continue;
          阶段.value = `合并第 ${下标 + 1}/${分组.length} 组…`;
          const 成员 = 组.map(uid => 待改表.get(uid)).filter(Boolean) as TargetPrompt[];
          if (成员.length <= 1) continue;

          const 合并后 = await 合并组(
            成员.map(m => ({ name: m.name, content: m.content ?? '' })),
            需求参数(),
            提示词.value.rewrite,
            应中止,
          );
          store.添加AI结果({
            id: 新结果id(),
            targetUids: 组,
            name: 成员[0].name,
            content: 合并后,
            mode: 'merged',
            createdAt: Date.now(),
            applied: false,
          });
          已产出++;
        }
      }

      toastr.success(
        已产出
          ? `已生成 ${已产出} 条改写结果，在下方「AI 生成条目」里勾选后替换`
          : '没有产生任何改写结果',
        '预设缝合助手',
      );
    },
    () => 执行改写(模式),
  );
}

/* ============ AI 结果的替换 ============ */

/**
 * 还没确认替换的结果。
 * 已确认的从列表里消失：它的内容已经进了目标条目，
 * 再挂在待办列表里只会让人以为还有事没做完。
 */
const 待确认结果 = computed(() => 槽位.value.aiResults.filter(r => !r.applied));

function 切换结果勾选(id: string) {
  const 下一个 = new Set(结果勾选.value);
  下一个.has(id) ? 下一个.delete(id) : 下一个.add(id);
  结果勾选.value = 下一个;
}

/** 替换选中：交给 App 建对比队列，进条目编辑器逐条确认 */
function 替换选中() {
  const ids = [...结果勾选.value].filter(id => 待确认结果.value.some(r => r.id === id));
  if (ids.length === 0) {
    toastr.warning('先勾选要替换的条目', '预设缝合助手');
    return;
  }
  emit('开始对比', ids);
}

/** 全部替换：跳过逐条确认，一次覆盖 */
function 全部替换() {
  const 数 = 待确认结果.value.length;
  if (数 === 0) {
    toastr.info('没有待替换的条目', '预设缝合助手');
    return;
  }
  if (!confirm(`确定把 ${数} 条 AI 生成结果全部替换进目标条目吗？合并模式的结果会同时移除其余成员条目。`)) {
    return;
  }
  const 成功 = store.全部应用AI结果();
  结果勾选.value = new Set();
  toastr.success(`已替换 ${成功} / ${数} 条`, '预设缝合助手');
}

/* ============ 正则筛选 ============ */

async function 执行正则筛选() {
  if (!查找关键词.value.trim()) {
    toastr.warning('请先填写需求', '预设缝合助手');
    return;
  }
  const 参与集 = new Set(参与预设.value.map(i => i.id));
  const 全部 = store.正则来源.filter(e => 参与集.has(e.presetId));
  if (全部.length === 0) {
    toastr.warning('限定范围内没有正则', '预设缝合助手');
    return;
  }

  await 运行(
    async () => {
      阶段.value = `筛选中（共 ${全部.length} 条）…`;
      const 结果 = await 正则筛选(
        全部.map(e => ({
          id: e.regex.id,
          name: `${e.presetName} · ${e.regex.script_name}`,
          find: e.regex.find_regex,
        })),
        查找关键词.value,
        提示词.value.regex,
        应中止,
      );
      const 名称表 = new Map(全部.map(e => [e.regex.id, e.regex.script_name]));
      正则候选.value = 结果.map(r => ({ id: r.id, 名称: 名称表.get(r.id) ?? r.id, 理由: r.理由 }));
      toastr.success(`筛出 ${正则候选.value.length} 条相关正则`, '预设缝合助手');
    },
    执行正则筛选,
  );
}

function 加入正则(id: string) {
  const entry = store.正则来源.find(e => e.regex.id === id);
  if (!entry) return;
  if (槽位.value.regexes.some(r => r.id === id)) {
    toastr.info('该正则已在目标中', '预设缝合助手');
    return;
  }
  store.批量加入正则([deepClone(entry.regex)]);
}

