<script setup lang="ts">
import { computed, ref } from 'vue';
import { detectRegexConflicts } from '../core/regex.ts';
import { useWorkspaceStore } from '../core/store.ts';

const emit = defineEmits<{ 选中编辑器: [index: number] }>();

const store = useWorkspaceStore();
const 拖拽索引 = ref<number | null>(null);
const 批量模式 = ref(false);
const 勾选 = ref<Set<string>>(new Set());

const 列表 = computed(() => store.slot.regexes);
const 冲突 = computed(() => detectRegexConflicts(列表.value));

const 冲突说明 = computed(() => {
  const 映射 = new Map<string, string>();
  for (const c of 冲突.value) {
    const 文案 =
      c.type === 'exact_duplicate'
        ? '查找表达式与另一条完全相同'
        : c.type === 'similar'
          ? `与另一条高度相似（${(c.similarity * 100).toFixed(0)}%）`
          : '与另一条的作用范围、用途完全一致，可能互相影响';
    for (const id of c.regexIds) if (!映射.has(id)) 映射.set(id, 文案);
  }
  return 映射;
});

/**
 * 正则按顺序生效，顺序本身就是语义的一部分，所以拖拽调序是核心操作。
 */
function 落位(目标下标: number) {
  if (拖拽索引.value === null || 拖拽索引.value === 目标下标) return;
  store.移动正则(拖拽索引.value, 目标下标);
  拖拽索引.value = null;
}

function 切换勾选(id: string) {
  const 下一个 = new Set(勾选.value);
  下一个.has(id) ? 下一个.delete(id) : 下一个.add(id);
  勾选.value = 下一个;
}

function 全选() {
  勾选.value = 勾选.value.size > 0 ? new Set() : new Set(列表.value.map(r => r.id));
}

function 批量移除() {
  const 数 = 勾选.value.size;
  for (const id of 勾选.value) store.移除正则(id);
  勾选.value = new Set();
  toastr.success(`已移除 ${数} 条正则`, '预设缝合助手');
}

function 点击(id: string, index: number) {
  if (批量模式.value) 切换勾选(id);
  else emit('选中编辑器', index);
}
</script>

<template>
  <div class="flex flex-col flex-1 min-h-0">
    <div class="p-2 border-b border-line shrink-0 flex items-center gap-2 text-xs">
      <span>目标 {{ 列表.length }} 条</span>
      <span v-if="冲突.length" class="text-warn">
        <i class="fa-solid fa-triangle-exclamation" /> {{ 冲突.length }}
      </span>
      <button
        class="ml-auto px-1.5 py-0.5 rounded border text-[11px] transition-colors"
        :class="批量模式 ? 'border-accent text-accent bg-accent-soft/40' : 'border-line hover:border-line-strong'"
        @click="批量模式 = !批量模式"
      >
        <i class="fa-solid fa-list-check" /> 批量
      </button>
    </div>

    <div v-if="批量模式" class="px-2 py-1 border-b border-line flex items-center gap-1.5 text-[11px] shrink-0">
      <button class="px-1.5 py-0.5 rounded border border-line hover:border-accent" @click="全选">
        {{ 勾选.size ? '全不选' : '全选' }}
      </button>
      <button
        class="px-2 py-0.5 rounded border border-danger text-danger disabled:opacity-40"
        :disabled="勾选.size === 0"
        @click="批量移除"
      >
        移除 {{ 勾选.size }} 条
      </button>
    </div>

    <div class="flex-1 overflow-y-auto">
      <div v-if="列表.length === 0" class="p-3 text-xs text-muted leading-relaxed">
        从左边点选正则加入目标。<br />正则<b>按顺序生效</b>，加进来后可以拖拽调序。
      </div>

      <div
        v-for="(regex, index) in 列表"
        :key="regex.id"
        :draggable="!批量模式"
        class="px-2 py-1 border-b border-line/40 text-xs transition-colors"
        :class="[
          批量模式 ? 'cursor-default' : 'cursor-grab hover:bg-surface2/60',
          冲突说明.has(regex.id) ? 'border-l-2 border-l-warn bg-warn/10' : '',
        ]"
        :title="冲突说明.get(regex.id) ?? ''"
        @dragstart="拖拽索引 = index"
        @dragover.prevent
        @drop="落位(index)"
        @click="点击(regex.id, index)"
      >
        <div class="flex items-center gap-1.5">
          <input
            v-if="批量模式"
            type="checkbox"
            class="shrink-0"
            :checked="勾选.has(regex.id)"
            @click.stop="切换勾选(regex.id)"
          />
          <span v-else class="text-muted text-[10px] shrink-0 w-4 text-right">{{ index + 1 }}</span>
          <span class="truncate flex-1">{{ regex.script_name }}</span>
          <span v-if="!regex.enabled" class="text-[10px] text-muted shrink-0">禁用</span>
          <button
            class="text-muted hover:text-danger shrink-0"
            title="移除"
            @click.stop="store.移除正则(regex.id)"
          >
            <i class="fa-solid fa-xmark" />
          </button>
        </div>
        <div class="text-[10px] text-muted truncate font-mono pl-5 opacity-70">{{ regex.find_regex }}</div>
      </div>
    </div>
  </div>
</template>
