<script setup lang="ts">
import { computed } from 'vue';
import { 参数表, 读取参数 } from '../core/params.ts';
import { useWorkspaceStore } from '../core/store.ts';

const store = useWorkspaceStore();

const 槽位 = computed(() => store.slot);

/** 骨架预设里实际存在的参数值，用于显示「继承自骨架」的灰字提示 */
const 骨架参数 = computed(() => 读取参数(store.skeleton?.raw.settings ?? null));

/** 当前生效值 = 骨架值被用户覆盖后的结果 */
const 生效值 = computed(() => ({ ...骨架参数.value, ...槽位.value.paramsOverride }));

/** 哪些参数是用户手动覆盖过的 */
function 已覆盖(名: string): boolean {
  return 槽位.value.paramsOverride[名] !== undefined;
}

function 改参数(名: string, 值: number | boolean) {
  const 下一个 = { ...槽位.value.paramsOverride };
  下一个[名] = 值;
  槽位.value.paramsOverride = 下一个;
  store.save();
}

function 恢复继承(名: string) {
  const 下一个 = { ...槽位.value.paramsOverride };
  delete 下一个[名];
  槽位.value.paramsOverride = 下一个;
  store.save();
}

function 全部恢复继承() {
  槽位.value.paramsOverride = {};
  store.save();
  toastr.success('已全部恢复为继承骨架预设', '预设缝合助手');
}

const 覆盖数 = computed(() => Object.keys(槽位.value.paramsOverride).length);
</script>

<template>
  <div class="flex flex-col flex-1 min-h-0">
    <div class="px-2 py-1.5 border-b border-line shrink-0 flex items-center gap-2 text-[11px]">
      <span class="text-muted">全局参数</span>
      <span v-if="覆盖数" class="text-accent">已覆盖 {{ 覆盖数 }}</span>
      <button
        v-if="覆盖数"
        class="ml-auto text-muted hover:text-accent"
        title="全部恢复为继承骨架预设的参数"
        @click="全部恢复继承"
      >
        恢复继承
      </button>
    </div>

    <div class="flex-1 overflow-y-auto p-2 space-y-1">
      <div
        v-for="定义 in 参数表"
        :key="定义.名"
        class="flex items-center gap-1.5 text-[11px]"
        :title="定义.说明 ?? ''"
      >
        <span class="w-24 shrink-0 truncate" :class="已覆盖(定义.名) ? 'text-accent' : 'text-muted'">
          {{ 定义.名 }}
        </span>

        <template v-if="定义.类型 === 'boolean'">
          <input
            type="checkbox"
            :checked="Boolean(生效值[定义.名] ?? 定义.默认值)"
            @change="改参数(定义.名, ($event.target as HTMLInputElement).checked)"
          />
          <span class="text-muted">{{ 生效值[定义.名] ? '开' : '关' }}</span>
        </template>

        <template v-else>
          <input
            type="number"
            class="flex-1 min-w-0 py-0.5"
            :step="定义.步进 ?? 1"
            :value="生效值[定义.名] ?? 定义.默认值"
            @change="改参数(定义.名, Number(($event.target as HTMLInputElement).value))"
          />
        </template>

        <button
          v-if="已覆盖(定义.名)"
          class="shrink-0 text-muted hover:text-warn"
          title="恢复为继承骨架预设"
          @click="恢复继承(定义.名)"
        >
          <i class="fa-solid fa-rotate-left" />
        </button>
      </div>

      <p class="text-[10px] text-muted leading-relaxed pt-1">
        蓝色的参数是你手动覆盖的，其余继承骨架预设。
        骨架预设本身不带参数时（例如剧作家预设），这里就是唯一的参数来源。
      </p>
    </div>
  </div>
</template>
