import { 应用参数 } from './params.ts';
import { createOrReplacePreset, ensurePresetRegexAllowed, loadPreset } from './tavern.ts';
import {
  VARIABLE_CONSOLE_UID,
  entryKind,
  type ImportedPreset,
  type Preset,
  type PresetPrompt,
  type StitchSlot,
} from '../types.ts';

/** 骨架的 settings 可能是响应式对象，用 JSON 往返脱掉 Proxy（不能用 structuredClone） */
function structuredCloneSafe<T>(值: T): T {
  return JSON.parse(JSON.stringify(值 ?? {})) as T;
}

/**
 * 把一个缝合槽位组装成完整预设对象。
 *
 * 依据已核实的事实:
 * - 酒馆按 prompts 数组顺序重建 prompt_order, 所以数组顺序即相对顺序
 * - 系统词/占位符 id 重复会让酒馆拒绝写入, 所以这两类只允许骨架提供
 * - 正则写在 extensions.regex_scripts 即可
 *
 * 一次组装成完整对象而非分步写, 是为了避免中途失败留下半成品预设。
 */
export function assemblePreset(slot: StitchSlot, imports: ImportedPreset[]): Preset | { error: string } {
  const skeleton = imports.find(i => i.id === slot.skeletonId);
  if (!skeleton) return { error: '尚未选择骨架预设，请先在左栏点某个预设前的 ☆' };

  const skeletonPrompts = [...(skeleton.raw.prompts ?? []), ...(skeleton.raw.prompts_unused ?? [])];

  // 1. 系统词与占位符: 只取骨架的
  const systemAndPlaceholder = skeletonPrompts.filter(p => entryKind(p) !== 'normal');

  // 2. 普通条目: 目标栏里的全部条目, 剥离内部字段
  const normalPrompts: PresetPrompt[] = slot.prompts.map(
    ({ _uid, _from, _origin, _mode, ...rest }) => rest as PresetPrompt,
  );

  /*
   * 3. 排布顺序。
   *
   * 骨架原本的普通条目默认全部排除(用户没勾选就不搬), 但系统词与占位符
   * 必须整体保留原有的相对顺序 —— 它们决定了角色卡、世界书、聊天记录插在哪。
   *
   * 新条目插在「第一个占位符之前」, 也就是紧挨着开场指令区域。
   * 为什么不用「最后一个占位符之前」: 实测用户的剧作家预设里 chatHistory 在
   * 第 159/202 位, 它后面还有 43 条普通条目和系统词 ——
   * 「chatHistory 必须在最后」只是酒馆默认预设的惯例, 不是硬约束。
   */
  let insertAt = systemAndPlaceholder.length;
  const 首个占位符 = systemAndPlaceholder.findIndex(p => entryKind(p) === 'placeholder');
  if (首个占位符 !== -1) insertAt = 首个占位符;

  const prompts: PresetPrompt[] = [
    ...systemAndPlaceholder.slice(0, insertAt),
    ...normalPrompts,
    ...systemAndPlaceholder.slice(insertAt),
  ];

  // 全局参数：骨架自带的参数打底，再叠加用户在参数面板里的覆盖
  const 设置 = structuredCloneSafe(skeleton.raw.settings ?? {});
  应用参数(设置, slot.paramsOverride ?? {});

  return {
    settings: 设置,
    prompts,
    prompts_unused: [],
    extensions: {
      ...JSON.parse(JSON.stringify(skeleton.raw.extensions ?? {})),
      regex_scripts: slot.regexes,
    },
  };
}

/** 变量控制台是否已在槽位中 */
export function hasVariableConsole(slot: StitchSlot): boolean {
  return slot.prompts.some(t => t._uid === VARIABLE_CONSOLE_UID);
}

/** 取某个导入预设中指定 id 的条目, 供界面显示来源信息 */
export function findSourcePrompt(imported: ImportedPreset, promptId: string): PresetPrompt | null {
  const all = [...(imported.raw.prompts ?? []), ...(imported.raw.prompts_unused ?? [])];
  return all.find(p => p.id === promptId) ?? null;
}

/** 生成带时间戳的默认槽位/预设名 */
export function 生成默认预设名(): string {
  const now = new Date();
  const pad = (n: number) => String(n).padStart(2, '0');
  return `缝合_${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}`;
}

/**
 * 把组装好的预设写入酒馆并切换启用。
 */
export async function syncToTavern(preset: Preset, name: string): Promise<{ created: boolean }> {
  const created = await createOrReplacePreset(name, preset);
  loadPreset(name);
  ensurePresetRegexAllowed(name);
  return { created };
}
