<script setup lang="ts">
/**
 * 手机版悬浮球：把「切换页签」从屏幕顶端挪到大拇指够得到的地方。
 *
 * 为什么它是「薄壳」、自己不读 store：
 * 页签数据（名字 + 数量徽标 + 切模式时整套更换）只有 App.vue 的 `页签表` 一处来源。
 * 球若自己再算一份，切模式时两边必然不同步；复用同一个 `页签表`，
 * 「目录和最上面的按钮一致」就是天然成立的，不需要额外维护一张对照表。
 */
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { 读取界面设置, 写入界面设置, type 吸附边 } from '../界面设置.ts';

const props = defineProps<{
  /** 与顶部页签栏同源：同名、同顺序、同数量徽标 */
  页签表: { key: string; 名: string; 数: number }[];
  /** 当前页签 key，用于在目录里高亮 */
  当前: string;
}>();

const emit = defineEmits<{ 切换: [key: string] }>();

/* ============ 尺寸常量 ============ */

const 球直径 = 44; // 触控目标下限 44×44
const 停靠边距 = 12; // 吸附后距屏幕边缘
const 视口留白 = 8; // 拖动时四周至少留这么多，防止贴死边缘难按
const 目录间距 = 8; // 目录与球之间留的空隙
const 拖动阈值 = 6; // 位移超过它才算拖动，否则算点击
const 操作条高 = 50; // 底部操作条高度 —— 初始位置必须避开它
const 底部间距 = 12;

/** 数量徽标：超过两位数收成 99+，否则会把目录撑宽（与顶部页签栏同一套规则） */
function 徽标(数: number): string {
  return 数 > 99 ? '99+' : String(数);
}

/* ============ 状态 ============ */

const 球 = ref<HTMLElement | null>(null);

/** 停靠边 */
const 边 = ref<吸附边>('left');
/** 球顶边距视口上沿的像素。纵向完全自由，不做吸附 */
const 纵向 = ref(0);

const 视口宽 = ref(window.innerWidth);
const 视口高 = ref(window.innerHeight);

const 目录开 = ref(false);
/** 拖动中：球改用指针坐标定位，松手后才落回「停靠边 + 纵向」 */
const 拖动中 = ref(false);
const 拖动位置 = ref<{ x: number; y: number } | null>(null);

function 钳制(值: number, 下限: number, 上限: number): number {
  return Math.min(Math.max(值, 下限), Math.max(下限, 上限));
}

/* ============ 当前位置（球与目录共用同一份，避免两边算出不一致的位置）============ */

const 有效位置 = computed(() => {
  if (拖动位置.value) {
    return {
      左: 拖动位置.value.x,
      顶: 拖动位置.value.y,
      边: (拖动位置.value.x + 球直径 / 2 < 视口宽.value / 2 ? 'left' : 'right') as 吸附边,
    };
  }
  return {
    左: 边.value === 'left' ? 停靠边距 : 视口宽.value - 球直径 - 停靠边距,
    顶: 纵向.value,
    边: 边.value,
  };
});

const 球样式 = computed(() => ({
  left: `${有效位置.value.左}px`,
  top: `${有效位置.value.顶}px`,
  // 定位改成纯 left：拖动时已经算好绝对坐标，再挂 right 会互相打架
  right: 'auto',
}));

/** 球在下半屏就往上弹目录 —— 否则靠底时目录会被屏幕下沿切掉 */
const 目录向上 = computed(() => 有效位置.value.顶 + 球直径 / 2 > 视口高.value / 2);

const 目录样式 = computed(() => {
  const 位置 = 有效位置.value;
  const 横向 =
    位置.边 === 'left'
      ? { left: `${停靠边距}px`, right: 'auto' }
      : { left: 'auto', right: `${停靠边距}px` };
  const 纵向 = 目录向上.value
    ? { top: 'auto', bottom: `${视口高.value - 位置.顶 + 目录间距}px` }
    : { top: `${位置.顶 + 球直径 + 目录间距}px`, bottom: 'auto' };
  return { ...横向, ...纵向 };
});

/* ============ 拖动 / 点击 ============ */

type 按下一刻 = { 指针x: number; 指针y: number; 球左: number; 球顶: number };
let 按下时: 按下一刻 | null = null;
let 已拖动 = false;

function 按下(e: PointerEvent) {
  // 鼠标只认左键；触屏/触控笔没有 button 概念，直接放行
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  const 元素 = e.currentTarget as HTMLElement;
  const 盒 = 元素.getBoundingClientRect();
  元素.setPointerCapture(e.pointerId);
  // 记下按下瞬间的球位，之后一律用「球位 + 位移」求新位，
  // 而不是每帧在当前位上累加 —— 后者会因舍入误差一路漂移
  按下时 = { 指针x: e.clientX, 指针y: e.clientY, 球左: 盒.left, 球顶: 盒.top };
  已拖动 = false;
}

function 移动(e: PointerEvent) {
  if (!按下时) return;
  const dx = e.clientX - 按下时.指针x;
  const dy = e.clientY - 按下时.指针y;
  if (!已拖动 && Math.hypot(dx, dy) < 拖动阈值) return;

  if (!已拖动) {
    已拖动 = true;
    拖动中.value = true;
    // 一开始拖就收起目录，否则目录会跟着手指在屏幕上乱飘
    目录开.value = false;
  }

  拖动位置.value = {
    x: 钳制(按下时.球左 + dx, 视口留白, 视口宽.value - 球直径 - 视口留白),
    y: 钳制(按下时.球顶 + dy, 视口留白, 视口高.value - 球直径 - 视口留白),
  };
}

/** 松手落位。拖动被打断时（来电、系统返回手势）不要把中断当成点击 */
function 结束(e: PointerEvent, 允许算点击: boolean) {
  const 元素 = e.currentTarget as HTMLElement;
  if (元素.hasPointerCapture(e.pointerId)) 元素.releasePointerCapture(e.pointerId);

  if (已拖动 && 拖动位置.value) {
    // 吸附到最近的一侧；纵向保持手指松开的位置
    边.value = 拖动位置.value.x + 球直径 / 2 < 视口宽.value / 2 ? 'left' : 'right';
    纵向.value = 拖动位置.value.y;
    保存位置();
  } else if (允许算点击 && 按下时) {
    // 位移没超过阈值 —— 当成点击，开合目录
    目录开.value = !目录开.value;
  }

  按下时 = null;
  已拖动 = false;
  拖动中.value = false;
  拖动位置.value = null;
}

/* ============ 位置持久化 ============ */

function 保存位置() {
  写入界面设置({ 悬浮球: { 边: 边.value, 纵向: 纵向.value } });
}

/**
 * 读面板量到的底部安全区。
 * 球是 position:fixed，拿不到根节点的 padding，所以初始位置必须自己减掉这块。
 * 值由手机版 index.ts 从酒馆页面实测后递进来。
 */
function 安全区下(): number {
  const 值 = getComputedStyle(document.documentElement).getPropertyValue('--面板安全区下');
  return parseFloat(值) || 0;
}

/** 默认落点：左下角，且避开底部操作条 —— 否则一上来就压住左边的「骨架」文字 */
function 算默认纵向(): number {
  return 钳制(
    视口高.value - 球直径 - 操作条高 - 底部间距 - 安全区下(),
    视口留白,
    视口高.value - 球直径 - 视口留白,
  );
}

function 同步视口() {
  视口宽.value = window.innerWidth;
  视口高.value = window.innerHeight;
  // 窗口变小（转屏、键盘弹起）后旧位置可能落到屏幕外，拉回可见范围
  纵向.value = 钳制(纵向.value, 视口留白, 视口高.value - 球直径 - 视口留白);
}

onMounted(() => {
  同步视口();
  const 存档 = 读取界面设置().悬浮球;
  if (存档) {
    边.value = 存档.边;
    纵向.value = 钳制(存档.纵向, 视口留白, 视口高.value - 球直径 - 视口留白);
  } else {
    边.value = 'left';
    纵向.value = 算默认纵向();
  }
  window.addEventListener('resize', 同步视口);
});

onBeforeUnmount(() => {
  window.removeEventListener('resize', 同步视口);
});

/* ============ 切页 ============ */

function 选(键: string) {
  目录开.value = false;
  // 点当前页就只是收起目录，不必白切一次（切页会触发组件重建 / v-show 切换）
  if (键 !== props.当前) emit('切换', 键);
}
</script>

<template>
  <!-- 目录。遮罩在球之上：菜单开着时点球，命中的是遮罩 → 先收起菜单，符合直觉 -->
  <template v-if="目录开">
    <div class="fixed inset-0 z-40" @click="目录开 = false" />

    <div
      class="fixed z-50 glass-strong rounded-xl p-1 min-w-36 text-[13px] max-h-[70vh] overflow-y-auto"
      :style="目录样式"
    >
      <button
        v-for="项 in 页签表"
        :key="项.key"
        class="w-full min-h-10 px-2.5 rounded-lg flex items-center gap-2 transition-colors"
        :class="
          项.key === 当前 ? 'bg-accent text-accent-text font-medium' : 'hover:bg-surface2 text-body'
        "
        @click="选(项.key)"
      >
        <span class="truncate flex-1 text-left">{{ 项.名 }}</span>
        <span v-if="项.数" class="shrink-0 text-[11px] opacity-75">{{ 徽标(项.数) }}</span>
      </button>
    </div>
  </template>

  <!--
    球本体。
    用 pointerdown/move/up 而不是 click：一套代码同时覆盖触屏与鼠标，
    还能和「位移超过阈值才算拖动」共存 —— 纯 click 拿不到拖动过程。
    touch-none 必须加：否则手指按下拖动时会先触发页面滚动，球跟不上手。
  -->
  <button
    ref="球"
    class="fixed z-30 w-11 h-11 rounded-full glass-strong flex items-center justify-center touch-none select-none cursor-grab"
    :class="拖动中 ? 'opacity-90 cursor-grabbing' : ''"
    :style="球样式"
    title="拖动可换位置，点一下展开页签目录"
    aria-label="页签目录"
    @pointerdown="按下"
    @pointermove="移动"
    @pointerup="e => 结束(e, true)"
    @pointercancel="e => 结束(e, false)"
  >
    <i class="fa-solid fa-grip text-2xl pointer-events-none" />
  </button>
</template>
