<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useWorkspaceStore } from '../core/store.ts';
import { entryKind, type PresetPrompt } from '../types.ts';

const props = defineProps<{ presetId: string | null }>();
const emit = defineEmits<{
  选择: [prompt: PresetPrompt, presetId: string];
  查看: [prompt: PresetPrompt, presetId: string];
}>();
const 批量模式 = defineModel<boolean>('批量模式', { default: false });

const store = useWorkspaceStore();
const 关键词 = ref('');
const 只看启用 = ref(false);
const 显示未使用 = ref(false);
const 只看变量 = ref(false);
const 勾选 = ref<Set<string>>(new Set());

const 当前预设 = computed(() => store.workspace.imports.find(i => i.id === props.presetId) ?? null);

/** 骨架已占用的系统词与占位符 —— 搬进来会让写入失败，必须置灰 */
const 骨架占用 = computed(() => {
  const skeleton = store.skeleton;
  if (!skeleton) return new Set<string>();
  return new Set(
    store
      .条目(skeleton)
      .filter(p => entryKind(p) !== 'normal')
      .map(p => p.id),
  );
});

const 列表 = computed(() => {
  if (!当前预设.value) return [];
  const 已用 = 当前预设.value.raw.prompts ?? [];
  const 未用 = 显示未使用.value ? (当前预设.value.raw.prompts_unused ?? []) : [];
  const kw = 关键词.value.trim();
  return [...已用, ...未用].filter(p => {
    if (只看启用.value && !p.enabled) return false;
    if (只看变量.value && !变量标记(p)) return false;
    if (kw && !p.name.includes(kw) && !(p.content ?? '').includes(kw)) return false;
    return true;
  });
});

/** 切换预设时清空勾选，避免勾选的条目张冠李戴 */
watch(() => props.presetId, () => { 勾选.value = new Set(); });
watch(批量模式, 开 => { if (!开) 勾选.value = new Set(); });

function 被骨架占用(prompt: PresetPrompt): boolean {
  return entryKind(prompt) !== 'normal' && 骨架占用.value.has(prompt.id);
}

function 已选中(prompt: PresetPrompt): boolean {
  return store.targetUidSet.has(`${props.presetId}::${prompt.id}`);
}

function 徽章(prompt: PresetPrompt): string {
  const kind = entryKind(prompt);
  return kind === 'system' ? '系统' : kind === 'placeholder' ? '占位' : '普通';
}

/**
 * 条目与变量的关系。
 * 区分「定义」和「引用」很有用：缝合时通常要把定义控制台一起搬走，
 * 否则搬过去的引用会变成空引用而静默失效。
 */
function 变量标记(prompt: PresetPrompt): '' | '定义' | '引用' {
  const 内容 = prompt.content ?? '';
  if (/\{\{(setvar|setglobalvar)::/.test(内容)) return '定义';
  if (/\{\{(getvar|getglobalvar)::/.test(内容)) return '引用';
  return '';
}

function 可操作(prompt: PresetPrompt): boolean {
  return !被骨架占用(prompt) && !!props.presetId;
}

/**
 * 单击一行 = 打开这个条目自己的编辑界面。
 *
 * 刻意不在这里「加入目标」：浏览源预设时想看看某条写了什么，是很自然的动作，
 * 如果顺手就把它缝进目标，用户会在没打算缝的时候把目标栏搞得一团乱。
 * 加入改成行尾那个 ＋ 按钮，动作明确、可撤销。
 */
function 点击(prompt: PresetPrompt) {
  if (批量模式.value) {
    if (可操作(prompt)) 切换勾选(prompt);
    return;
  }
  if (!props.presetId) return;
  emit('查看', prompt, props.presetId);
}

/** 行尾的 ＋ / ✓：加入或移出目标 */
function 切换加入(prompt: PresetPrompt) {
  if (!可操作(prompt)) {
    if (被骨架占用(prompt)) {
      toastr.info('该条目由骨架预设提供，同一个预设里不能有两份，因此无法缝入', '预设缝合助手');
    }
    return;
  }
  emit('选择', prompt, props.presetId!);
}

function 切换勾选(prompt: PresetPrompt) {
  const uid = `${props.presetId}::${prompt.id}`;
  const 下一个 = new Set(勾选.value);
  下一个.has(uid) ? 下一个.delete(uid) : 下一个.add(uid);
  勾选.value = 下一个;
}

/** 可批量操作的条目（排除骨架占用与已在目标中的） */
const 可批量列表 = computed(() => 列表.value.filter(p => 可操作(p) && !已选中(p)));

function 全选() {
  if (!props.presetId) return;
  // 已勾选则全不选，否则全选可加入的 —— 一个按钮完成全选/全不选切换
  if (勾选.value.size > 0) {
    勾选.value = new Set();
  } else {
    勾选.value = new Set(可批量列表.value.map(p => `${props.presetId}::${p.id}`));
  }
}

function 反选() {
  if (!props.presetId) return;
  const 全部 = new Set(可批量列表.value.map(p => `${props.presetId}::${p.id}`));
  const 下一个 = new Set<string>();
  for (const uid of 全部) if (!勾选.value.has(uid)) 下一个.add(uid);
  勾选.value = 下一个;
}

function 批量加入() {
  if (!props.presetId || !当前预设.value) return;
  const 待加 = store
    .条目(当前预设.value)
    .filter(p => 勾选.value.has(`${props.presetId}::${p.id}`))
    .map(prompt => ({ prompt, presetId: props.presetId! }));

  const 数 = store.批量加入条目(待加);
  勾选.value = new Set();
  toastr.success(数 ? `已批量加入 ${数} 条` : '勾选的条目都已在目标中', '预设缝合助手');
}
</script>

<template>
  <div class="flex flex-col flex-1 min-h-0">
    <div class="p-2 space-y-1.5 border-b border-line shrink-0">
      <input v-model="关键词" class="w-full text-xs" placeholder="搜索条目…" />

      <div class="flex items-center gap-2 flex-wrap text-[11px] text-muted">
        <label class="flex items-center gap-1 cursor-pointer">
          <input v-model="只看启用" type="checkbox" />只看启用
        </label>
        <label class="flex items-center gap-1 cursor-pointer">
          <input v-model="显示未使用" type="checkbox" />显示未使用
        </label>
        <label class="flex items-center gap-1 cursor-pointer" title="只显示含 {{setvar}} / {{getvar}} 的条目">
          <input v-model="只看变量" type="checkbox" /><span class="text-accent">只看变量</span>
        </label>
        <button
          class="ml-auto px-1.5 py-0.5 rounded border transition-colors"
          :class="批量模式 ? 'border-accent text-accent bg-accent-soft/40' : 'border-line hover:border-line-strong'"
          title="批量选择条目"
          @click="批量模式 = !批量模式"
        >
          <i class="fa-solid fa-list-check" /> 批量
        </button>
      </div>

      <!-- 批量操作条 -->
      <div v-if="批量模式" class="flex items-center gap-1.5 flex-wrap text-[11px]">
        <button class="px-1.5 py-0.5 rounded border border-line hover:border-accent" @click="全选">
          {{ 勾选.size ? '全不选' : '全选' }}
        </button>
        <button class="px-1.5 py-0.5 rounded border border-line hover:border-accent" @click="反选">反选</button>
        <button
          class="px-2 py-0.5 rounded bg-accent text-accent-text font-medium disabled:opacity-40"
          :disabled="勾选.size === 0"
          @click="批量加入"
        >
          加入 {{ 勾选.size }} 条
        </button>
        <span class="text-muted ml-auto">可加 {{ 可批量列表.length }}</span>
      </div>
    </div>

    <div class="flex-1 overflow-y-auto">
      <div v-if="!当前预设" class="p-3 text-xs text-muted">请先在左栏选择一个预设</div>
      <template v-else>
        <div v-if="列表.length === 0" class="p-3 text-xs text-muted">没有匹配的条目</div>

        <div
          v-for="prompt in 列表"
          :key="prompt.id"
          class="px-2 py-1 border-b border-line/40 flex items-center gap-1.5 text-xs transition-colors cursor-pointer"
          :class="[
            被骨架占用(prompt) ? 'opacity-45' : '',
            已选中(prompt) ? 'text-accent bg-accent-soft/25' : 'hover:bg-surface2/60',
          ]"
          @click="点击(prompt)"
        >
          <input
            v-if="批量模式"
            type="checkbox"
            class="shrink-0"
            :checked="勾选.has(`${presetId}::${prompt.id}`)"
            :disabled="!可操作(prompt) || 已选中(prompt)"
            @click.stop="切换勾选(prompt)"
          />

          <span class="shrink-0 text-[10px] px-1 rounded bg-surface2 text-muted">{{ 徽章(prompt) }}</span>
          <span
            v-if="变量标记(prompt)"
            class="shrink-0 text-[10px] px-1 rounded"
            :class="变量标记(prompt) === '定义' ? 'bg-warn/25 text-warn' : 'bg-accent-soft/50 text-accent'"
            :title="变量标记(prompt) === '定义' ? '这条条目定义了变量（含 setvar）' : '这条条目引用了变量（含 getvar）'"
          >
            变量·{{ 变量标记(prompt) }}
          </span>
          <span class="truncate flex-1">{{ prompt.name }}</span>
          <span v-if="prompt.position?.type === 'in_chat'" class="text-[10px] text-muted shrink-0">
            深{{ prompt.position.depth }}
          </span>
          <span v-if="!prompt.enabled" class="text-[10px] text-muted shrink-0">禁用</span>

          <!-- 行尾：加入 / 移出目标。单击整行是「查看」，加入必须走这里，避免误加 -->
          <button
            class="shrink-0 w-5 h-5 rounded flex items-center justify-center transition-colors"
            :class="[
              已选中(prompt) ? 'text-accent hover:text-danger' : 'text-muted hover:text-accent',
              { 'opacity-40 cursor-not-allowed': !可操作(prompt) },
            ]"
            :title="已选中(prompt) ? '已在目标中，点击移出' : '加入目标预设'"
            @click.stop="切换加入(prompt)"
          >
            <i :class="已选中(prompt) ? 'fa-solid fa-check' : 'fa-solid fa-plus'" />
          </button>
        </div>
      </template>
    </div>
  </div>
</template>
