import { assemblePreset, syncToTavern, 生成默认预设名 } from './preset.ts';
import { 需要补白名单 } from './tavern.ts';
import type { ImportedPreset, Preset } from '../types.ts';
import type { useWorkspaceStore } from './store.ts';

/**
 * 桌面版与手机版共用的高层动作。
 *
 * 抽出来的原因：这两个版本只是界面布局不同，背后的「组装 → 写入酒馆 → 切换启用」
 * 「把某个槽位的成品导入为源预设」等逻辑完全一样。放在这里两边共用，
 * 免得改一处忘一处。
 */

type 工作区Store = ReturnType<typeof useWorkspaceStore>;

/** 组装某个槽位，失败时用 toastr 提示并返回 null */
export function 组装槽位(
  store: 工作区Store,
  槽位id: string,
): { 槽位: ReturnType<() => 工作区Store['slot']>; 预设: Preset } | null {
  const 槽位 = store.workspace.slots.find(s => s.id === 槽位id);
  if (!槽位) return null;

  if (!store.workspace.imports.find(i => i.id === 槽位.skeletonId)) {
    toastr.warning('该槽位还没有选骨架预设（在预设列表里点 ☆）', '预设缝合助手');
    return null;
  }

  const 结果 = assemblePreset(槽位, store.workspace.imports);
  if ('error' in 结果) {
    toastr.error(结果.error, '预设缝合助手');
    return null;
  }
  return { 槽位, 预设: 结果 };
}

/** 把某个槽位写入酒馆并切换启用 */
export async function 同步槽位(store: 工作区Store, 槽位id: string): Promise<void> {
  const 组装结果 = 组装槽位(store, 槽位id);
  if (!组装结果) return;

  const 名称 = (组装结果.槽位.name || '').trim() || 生成默认预设名();
  store.重命名槽位(槽位id, 名称);

  const 正则数 = 组装结果.预设.extensions?.regex_scripts?.length ?? 0;
  const 需补白名单 = 正则数 > 0 && 需要补白名单(名称);

  try {
    const { created } = await syncToTavern(组装结果.预设, 名称);
    toastr.success(
      `已${created ? '新建' : '覆盖'}预设「${名称}」并切换启用` + (正则数 ? `，含 ${正则数} 条正则` : ''),
      '预设缝合助手',
    );
    if (需补白名单) {
      toastr.warning('预设正则可能未启用，请到酒馆「扩展 → 正则」中确认该预设被勾选', '预设缝合助手');
    }
  } catch (error) {
    console.error(error);
    toastr.error(`同步失败：${error instanceof Error ? error.message : String(error)}`, '预设缝合助手');
  }
}

/**
 * 把某个槽位的成品导入为一份待缝合的源预设。
 * 这样缝合出来的成品可以继续当素材，缝下一层。
 */
export function 导入槽位为源预设(store: 工作区Store, 槽位id: string): string | null {
  const 组装结果 = 组装槽位(store, 槽位id);
  if (!组装结果) return null;

  const 源名 = 组装结果.槽位.name || '未命名';
  const 导入项: ImportedPreset = {
    id: `slot-${槽位id}-${Date.now()}`,
    name: `【槽位】${源名}`,
    source: 'file',
    raw: 组装结果.预设,
    importedAt: Date.now(),
  };
  store.workspace.imports.push(导入项);
  store.save();
  toastr.success(`已把「${源名}」导入为源预设，可作为其他槽位的取材来源`, '预设缝合助手');
  return 导入项.id;
}
