/** 从酒馆原始预设里读出一组「当前生效」的参数值 */
export function 读取参数(settings: Record<string, any> | null | undefined): Record<string, number | boolean> {
  const 结果: Record<string, number | boolean> = {};
  const 源 = settings ?? {};

  for (const 定义 of 参数表) {
    const 命中 = 定义.读取字段.find(k => 源[k] !== undefined && 源[k] !== null);
    if (命中 === undefined) continue;

    const 原值 = 源[命中];
    if (定义.类型 === 'boolean') 结果[定义.名] = Boolean(原值);
    else {
      const 数 = Number(原值);
      结果[定义.名] = Number.isFinite(数) ? 数 : Number(定义.默认值);
    }
  }

  return 结果;
}

/**
 * 把参数覆盖应用到原始预设对象上。
 * 同时写「普通名」与「_openai 变体」，与酒馆助手的做法一致。
 */
export function 应用参数(
  原始: Record<string, any>,
  覆盖: Record<string, number | boolean>,
): Record<string, any> {
  for (const 定义 of 参数表) {
    const 值 = 覆盖[定义.名];
    // 只写用户真正设过的项：没设过就保持骨架预设原值
    if (值 === undefined || 值 === null) continue;
    for (const 字段 of 定义.字段) 原始[字段] = 值;
  }
  return 原始;
}

/** 界面显示用：把参数值格式化成短文本 */
export function 格式化参数值(定义: 参数定义, 值: number | boolean | undefined): string {
  if (值 === undefined) return '未设置';
  if (定义.类型 === 'boolean') return 值 ? '开' : '关';
  return String(值);
}
