import {
  createEmptySlot,
  createEmptyWorkspace,
  type AiResult,
  type StitchSlot,
  type Workspace,
} from '../types.ts';
import { 声明节点id } from './variables.ts';

/** 生成唯一 id。优先用浏览器的 crypto.randomUUID，退回随机串 */
export function 生成Id(): string {
  return crypto?.randomUUID?.() ?? `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/**
 * v1（一个工作区一份缝合结果）先摊平成 v2 形状，剩下的交给 规范化工作区 统一处理。
 * 只做形状转换，不在这里补 v3 字段 —— 补字段的逻辑只有一处在 补齐槽位。
 */
function 迁移v1(raw: Record<string, any>): Record<string, any> {
  const 槽位id = 生成Id();
  return {
    version: 2,
    theme: raw.theme,
    imports: Array.isArray(raw.imports) ? raw.imports : [],
    slots: [
      {
        id: 槽位id,
        name: raw.targetName ?? '',
        skeletonId: raw.skeletonId ?? null,
        paramsOverride: {},
        prompts: Array.isArray(raw.targetPrompts) ? raw.targetPrompts : [],
        regexes: Array.isArray(raw.regexes?.target) ? raw.regexes.target : [],
        variables: {
          agreedValue: raw.variables?.agreedValue ?? {},
          excluded: [],
          ignoredConsolePromptIds: raw.variables?.ignoredConsolePromptIds ?? [],
          consoleUid: raw.variables?.consoleUid ?? null,
          renderTemplate: raw.variables?.renderTemplate,
        },
      },
    ],
    activeSlotId: 槽位id,
    ai: {
      keyword: raw.ai?.keyword ?? '',
      injectionUids: raw.ai?.injectionUids ?? [],
      selectedPresetIds: raw.ai?.selectedPresetIds ?? [],
      // v1 的 mine/merge 合并语义已拆成 filter/rewrite，旧值按最接近的含义带过去
      prompts:
        raw.ai?.prompts === undefined
          ? undefined
          : {
              filter: raw.ai.prompts.mine ?? '',
              rewrite: raw.ai.prompts.merge ?? '',
              regex: raw.ai.prompts.regex ?? '',
            },
    },
  };
}

/**
 * 把任意版本的单个槽位补齐成 v3 形状。
 *
 * 逐字段显式列出，不用 `{...原始}` —— 用展开会把 v1/v2 的遗留字段（如 excluded）
 * 悄悄带进新结构，日后读数据的人分不清哪些字段还有意义。
 */
function 补齐槽位(原始: Record<string, any>): StitchSlot {
  const id = typeof 原始?.id === 'string' && 原始.id ? 原始.id : 生成Id();
  const 基础 = createEmptySlot(id, typeof 原始?.name === 'string' ? 原始.name : '');

  const 注入: Record<string, boolean> = { ...(原始?.variables?.injected ?? {}) };
  // v1/v2 的 excluded 是「不写进控制台」的名单，语义正好与注入开关相反
  if (Array.isArray(原始?.variables?.excluded)) {
    for (const 名 of 原始.variables.excluded) {
      if (typeof 名 === 'string' && 名) 注入[声明节点id(名)] = false;
    }
  }

  return {
    id,
    name: 基础.name,
    skeletonId: 原始?.skeletonId ?? null,
    paramsOverride:
      typeof 原始?.paramsOverride === 'object' && 原始.paramsOverride ? 原始.paramsOverride : {},
    prompts: Array.isArray(原始?.prompts) ? 原始.prompts : [],
    regexes: Array.isArray(原始?.regexes) ? 原始.regexes : [],
    aiResults: Array.isArray(原始?.aiResults) ? (原始.aiResults as AiResult[]) : [],
    variables: {
      agreedValue:
        typeof 原始?.variables?.agreedValue === 'object' && 原始.variables.agreedValue
          ? 原始.variables.agreedValue
          : {},
      injected: 注入,
      ignoredConsolePromptIds: Array.isArray(原始?.variables?.ignoredConsolePromptIds)
        ? 原始.variables.ignoredConsolePromptIds
        : [],
      consoleUid: 原始?.variables?.consoleUid ?? null,
      ai配对: Array.isArray(原始?.variables?.ai配对) ? 原始.variables.ai配对 : [],
      ai接管: Array.isArray(原始?.variables?.ai接管) ? 原始.variables.ai接管 : [],
      renderTemplate:
        typeof 原始?.variables?.renderTemplate === 'string'
          ? 原始.variables.renderTemplate
          : 基础.variables.renderTemplate,
    },
  };
}

/**
 * 把旧版存的「注入名单」换算成现在的「排除名单」。
 *
 * 语义在某一版反了过来：旧版是「勾选才注入」，现在是「缺省全注入、只记排除的」。
 * 直接丢掉旧名单会让用户在 8 条里挑的那 3 条变成「目标栏全部注入」，所以必须换算。
 *
 * 换算基准只取目标栏里真实存在的条目 —— 不在目标里的 uid 谈不上下次注不注入。
 */
function 换算旧注入名单(旧AI: Record<string, any>, 槽位: StitchSlot[]): string[] {
  if (Array.isArray(旧AI.injectionExcluded)) return 旧AI.injectionExcluded;

  const 旧注入: string[] = Array.isArray(旧AI.injectionUids) ? 旧AI.injectionUids : [];
  // 旧名单是空的，无法区分「从没动过」和「全取消过」。
  // 按「从没动过」处理：给新的默认值（全部注入），而不是把用户一下子清空。
  if (旧注入.length === 0) return [];

  // 过滤掉缺失 _uid 的脏数据，否则 undefined 会被塞进排除名单
  const 全部 = new Set(
    槽位
      .flatMap(s => s.prompts.map(p => p._uid))
      .filter((uid): uid is string => typeof uid === 'string' && uid.length > 0),
  );
  return [...全部].filter(uid => !旧注入.includes(uid));
}

/**
 * 把任意版本的原始数据规范化成当前版本（v3）的工作区。
 *
 * 【纯函数】：不碰酒馆 API、不读扩展设置，便于单测。
 * 数据的读取（`读取扩展数据()`）留在 store 里。
 */
export function 规范化工作区(raw: unknown): Workspace {
  if (!raw || typeof raw !== 'object') return createEmptyWorkspace();
  const 数据 = raw as Record<string, any>;
  if (!Array.isArray(数据.imports)) return createEmptyWorkspace();

  let 槽位数据: Record<string, any>[] = [];
  let 旧AI: Record<string, any> = {};

  if (数据.version === 1) {
    console.info('[预设缝合助手] 检测到 v1 工作区，已自动迁移到多槽位结构');
    const v2 = 迁移v1(数据);
    槽位数据 = v2.slots;
    旧AI = (v2.ai ?? {}) as Record<string, any>;
  } else if (数据.version === 2 || 数据.version === 3) {
    if (数据.version === 2) {
      console.info('[预设缝合助手] 检测到 v2 工作区，已补齐 AI 结果与注入开关字段');
    }
    槽位数据 = Array.isArray(数据.slots) ? 数据.slots : [];
    旧AI = (数据.ai ?? {}) as Record<string, any>;
  } else {
    return createEmptyWorkspace();
  }

  const 基础 = createEmptyWorkspace();
  const 槽位 = 槽位数据.map(补齐槽位);
  const 旧关键词 = typeof 旧AI.keyword === 'string' ? 旧AI.keyword : '';

  return {
    ...基础,
    imports: 数据.imports,
    slots: 槽位,
    activeSlotId: 槽位.some(s => s.id === 数据.activeSlotId) ? 数据.activeSlotId : (槽位[0]?.id ?? null),
    theme: 数据.theme === 'light' ? 'light' : 'dark',
    ai: {
      ...基础.ai,
      // v2 只有一个关键词，两个新字段都继承它，避免用户输入丢失
      searchKeyword: typeof 旧AI.searchKeyword === 'string' ? 旧AI.searchKeyword : 旧关键词,
      rewriteKeyword: typeof 旧AI.rewriteKeyword === 'string' ? 旧AI.rewriteKeyword : 旧关键词,
      injectionExcluded: 换算旧注入名单(旧AI, 槽位),
      selectedPresetIds: Array.isArray(旧AI.selectedPresetIds) ? 旧AI.selectedPresetIds : [],
      prompts: { ...基础.ai.prompts, ...(旧AI.prompts ?? {}) },
    },
    version: 3,
  };
}
